const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.1",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─── ENUMS ────────────────────────────────────────────────────────────────────\n\nenum UserRole {\n  SUPER_ADMIN\n  ADMIN_RRHH\n  GERENTE\n  SUPERVISOR\n  CONTADOR\n  EMPLEADO\n  AUDITOR\n}\n\nenum EstadoEmpleado {\n  ACTIVO\n  INACTIVO\n  SUSPENDIDO\n  VACACIONES\n  PERMISO\n}\n\nenum TipoContrato {\n  INDEFINIDO\n  TEMPORAL\n  PRUEBA\n  SERVICIO\n}\n\nenum TipoPlanilla {\n  SEMANAL\n  QUINCENAL\n  MENSUAL\n}\n\nenum EstadoPlanilla {\n  BORRADOR\n  CALCULADA\n  APROBADA\n  PAGADA\n  ANULADA\n}\n\nenum TipoDeduccion {\n  LEGAL\n  VOLUNTARIA\n  PRESTAMO\n  ADELANTO\n  COOPERATIVA\n  IMPUESTO\n  AFP\n  OTRO\n  /// Pensión alimenticia por orden judicial: hasta el 50 % del salario, incluso del mínimo (Art. 371, 1.º).\n  PENSION_ALIMENTICIA\n  /// Embargo judicial ordinario: sólo la cuarta parte del excedente del salario mínimo (Art. 371).\n  EMBARGO\n}\n\nenum ModoCalculoDeduccion {\n  PORCENTAJE\n  MONTO_FIJO\n}\n\nenum TipoPermiso {\n  VACACIONES\n  ENFERMEDAD\n  PERSONAL\n  MATERNIDAD\n  PATERNIDAD\n  DUELO\n  SIN_GOCE\n  OTRO\n}\n\nenum TipoEvaluacion {\n  DESEMPENO_MENSUAL\n  COMPETENCIA_TRIMESTRAL\n}\n\nenum EstadoEvaluacion {\n  BORRADOR\n  EN_PROGRESO\n  PENDIENTE_FIRMA\n  FINALIZADA\n  CANCELADA\n}\n\nenum RolEvaluador {\n  AUTOEVALUACION\n  JEFE_DIRECTO\n  PAR\n  SUBORDINADO\n  RRHH\n}\n\nenum NivelCompetencia {\n  INICIAL // 1\n  BASICO // 2\n  INTERMEDIO // 3\n  AVANZADO // 4\n  EXPERTO // 5\n}\n\nenum EstadoCampana {\n  PROGRAMADA\n  EN_PROGRESO\n  FINALIZADA\n  CANCELADA\n}\n\nenum AccionAudit {\n  CREATE\n  UPDATE\n  DELETE\n  APPROVE\n  SIGN\n  LOGIN\n  LOGOUT\n  // Una exportación se lleva identidades, RTN, salarios y cuentas bancarias\n  // fuera del sistema, y una importación los altera en masa. Las dos son tan\n  // auditables como aprobar una planilla, y no cabían en las acciones de arriba.\n  EXPORT\n  IMPORT\n}\n\nenum TipoDocumento {\n  DPI\n  RTN\n  TITULO\n  CERTIFICADO\n  CONTRATO\n  OTRO\n}\n\n// ─── EMPRESA & ESTRUCTURA ────────────────────────────────────────────────────\n\nmodel Empresa {\n  id        String   @id @default(cuid())\n  nombre    String\n  rtn       String   @unique\n  direccion String?\n  telefono  String?\n  email     String?\n  logoUrl   String?\n  activa    Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  sucursales Sucursal[]\n  planillas  Planilla[]\n}\n\nmodel Sucursal {\n  id           String   @id @default(cuid())\n  nombre       String\n  codigo       String\n  direccion    String?\n  telefono     String?\n  email        String?\n  /// Para qué sirve, cuando la sucursal funciona como grupo de nómina (ver «Jerarquía de nómina»).\n  descripcion  String?\n  activa       Boolean  @default(true)\n  /// Sucursal (BPLID) equivalente en SAP Business One, si SAP usa varias sucursales.\n  sapBplId     Int?\n  sapBplNombre String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  empresaId          String\n  empresa            Empresa             @relation(fields: [empresaId], references: [id])\n  divisiones         Division[]\n  departamentos      Departamento[]\n  empleados          Empleado[]\n  planillas          Planilla[]\n  coberturas         CoberturaSucursal[]\n  horariosAtencion   HorarioAtencion[]\n  detallesPlanilla   PlanillaDetalle[]\n  trasladosRecibidos TrasladoTemporal[]\n  logo               LogoSucursal?\n}\n\n/**\n * Logo de una sucursal, opcional. Sale en sus comprobantes y documentos.\n * En la base y no en disco: el disco de Seenode se borra en cada despliegue, y\n * así el logo entra en el respaldo y se conserva al reinstalar. En tabla aparte\n * y no en `Sucursal`: decenas de consultas hacen `sucursal.findMany()` sin\n * `select`, y arrastrarían los bytes hasta las pantallas.\n * Es siempre un PNG ya recortado y reducido: ver `lib/organizacion/logo.ts`.\n */\nmodel LogoSucursal {\n  sucursalId String   @id\n  sucursal   Sucursal @relation(fields: [sucursalId], references: [id], onDelete: Cascade)\n  png        Bytes\n  ancho      Int\n  alto       Int\n  updatedAt  DateTime @updatedAt\n}\n\n/**\n * División: nivel intermedio entre la sucursal y el departamento\n * (Sucursal → División → Departamento → Empleado). Sirve para clientes que\n * agrupan varias empresas o unidades de negocio bajo una misma nómina, p. ej.\n * «NOMINA CONFIDENCIAL» → «PAGSA MAYOREO» → «Administración».\n * Es OPCIONAL: una sucursal sin divisiones funciona como antes y sus\n * departamentos cuelgan directo de ella. Cuando una sucursal tiene divisiones\n * activas, la API exige que cada departamento nuevo o editado elija una\n * (ver `src/lib/organizacion/estructura.ts`).\n */\nmodel Division {\n  id          String   @id @default(cuid())\n  nombre      String\n  codigo      String?\n  descripcion String?\n  /// RTN propio, cuando la división es una empresa con razón social aparte (ver «Jerarquía de nómina»).\n  rtn         String?\n  activa      Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  sucursalId       String\n  sucursal         Sucursal          @relation(fields: [sucursalId], references: [id])\n  departamentos    Departamento[]\n  planillas        Planilla[]\n  detallesPlanilla PlanillaDetalle[]\n\n  @@unique([sucursalId, nombre])\n}\n\nmodel Departamento {\n  id          String   @id @default(cuid())\n  nombre      String\n  codigo      String?\n  descripcion String?\n  activo      Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  sucursalId       String\n  sucursal         Sucursal          @relation(fields: [sucursalId], references: [id])\n  /**\n   * División a la que pertenece. Opcional en la base para no romper los\n   * departamentos que ya existían (ver `Division`). Debe ser de la MISMA\n   * sucursal que el departamento; la API lo valida.\n   */\n  divisionId       String?\n  division         Division?         @relation(fields: [divisionId], references: [id], onDelete: Restrict)\n  /**\n   * Centro de costo POR OMISIÓN de quien trabaja aquí. Es la asignación normal:\n   * casi todo el mundo imputa a su departamento. La excepción se resuelve en el\n   * propio empleado (ver `Empleado.centroCostoId`).\n   */\n  centroCostoId    String?\n  centroCosto      CentroCosto?      @relation(fields: [centroCostoId], references: [id])\n  empleados        Empleado[]\n  puestos          Puesto[]\n  vacantes         Vacante[]\n  planillas        Planilla[]\n  detallesPlanilla PlanillaDetalle[]\n\n  @@index([centroCostoId])\n  @@index([divisionId])\n}\n\n/**\n * Centro de costo: la SEGUNDA dimensión del asiento contable.\n * No es una cuenta. La cuenta dice QUÉ es el gasto (5101 Sueldos); el centro de\n * costo dice DÓNDE se imputa (Producción, Administración). El asiento pasa de\n * una lista de cuentas a una matriz cuenta × centro.\n * `cuentaGasto` es opcional y sirve para el caso en que la contabilidad quiera\n * una cuenta distinta por centro (p. ej. 5101-01 para Producción). Vacío = se usa\n * la cuenta del plan general.\n */\nmodel CentroCosto {\n  id             String   @id @default(cuid())\n  codigo         String   @unique\n  nombre         String\n  descripcion    String?\n  /**\n   * Sufijo o cuenta propia para el plan contable. Opcional.\n   */\n  cuentaGasto    String?\n  /// Código del centro de costo (CostingCode de la dimensión elegida) en SAP B1.\n  /// Vacío = este centro no se puede repartir en SAP.\n  sapCostingCode String?\n  /// Proyecto de SAP B1 (ProjectCode) que acompaña a las líneas del centro. Opcional.\n  sapProjectCode String?\n  activo         Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  departamentos Departamento[]\n  empleados     Empleado[]\n}\n\n/// Clasificación de una cuenta del catálogo (NIIF para PYMES).\nenum TipoCuentaContable {\n  ACTIVO\n  PASIVO\n  PATRIMONIO\n  INGRESO\n  COSTO\n  GASTO\n}\n\n/// Lado en el que la cuenta acumula su saldo normal.\nenum NaturalezaSaldo {\n  DEUDORA\n  ACREEDORA\n}\n\n/**\n * Catálogo contable (plan de cuentas) de la empresa, con la misma estructura que\n * el de Gestión360: árbol por `padreCodigo`, cuentas de grupo y de detalle, tipo\n * NIIF y naturaleza del saldo. Sólo las cuentas de DETALLE reciben asientos.\n * `esSistema` marca las sembradas por la aplicación: se les cambia el nombre y\n * se desactivan, pero no se borran ni se recodifican, porque el mapeo de la\n * nómina las toma como valores por omisión.\n */\nmodel CuentaContable {\n  id              String             @id @default(cuid())\n  codigo          String             @unique\n  nombre          String\n  descripcion     String?\n  // Con valor por omisión para que la columna pueda añadirse a una tabla con\n  // filas sin pedir --accept-data-loss; toda alta la fija explícitamente.\n  tipo            TipoCuentaContable @default(ACTIVO)\n  naturaleza      NaturalezaSaldo    @default(DEUDORA)\n  /// Código de la cuenta madre; vacío = nivel 1.\n  padreCodigo     String?\n  esDetalle       Boolean            @default(true)\n  esSistema       Boolean            @default(false)\n  activa          Boolean            @default(true)\n  // ─── SAP Business One ───────────────────────────────────────────────────\n  /// AcctCode (código interno) de la cuenta equivalente en SAP B1. Vacío = sin mapeo.\n  sapAcctCode     String?\n  /// Nombre y estado leídos de SAP en la última verificación, para mostrarlos.\n  sapNombre       String?\n  sapActiva       Boolean?\n  sapVerificadaAt DateTime?\n  createdAt       DateTime           @default(now())\n  updatedAt       DateTime           @updatedAt\n\n  mapeos MapeoContable[]\n\n  @@index([padreCodigo])\n  @@index([tipo, activa])\n}\n\n/**\n * Qué cuenta del catálogo recibe cada CONCEPTO de la nómina.\n * `clave` es el concepto del motor (`sueldos`, `isrPorPagar`, ver `CUENTAS` en\n * lib/payroll/partida-contable.ts) y no cambia nunca; la cuenta la elige el\n * contador entre las de detalle del catálogo. Sin fila, o con `cuentaId` nulo,\n * el motor cae a la cuenta por omisión del concepto.\n */\nmodel MapeoContable {\n  clave     String          @id\n  cuentaId  String?\n  cuenta    CuentaContable? @relation(fields: [cuentaId], references: [id])\n  updatedAt DateTime        @updatedAt\n\n  @@index([cuentaId])\n}\n\nmodel Puesto {\n  id            String   @id @default(cuid())\n  nombre        String\n  descripcion   String?\n  salarioMinimo Decimal  @default(0) @db.Decimal(12, 2)\n  salarioMaximo Decimal  @default(0) @db.Decimal(12, 2)\n  activo        Boolean  @default(true)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  departamentoId     String\n  departamento       Departamento        @relation(fields: [departamentoId], references: [id])\n  empleados          Empleado[]\n  puestosCompetencia PuestoCompetencia[]\n  coberturas         CoberturaSucursal[]\n}\n\n// ─── USUARIOS ────────────────────────────────────────────────────────────────\n\nmodel User {\n  id                  String        @id @default(cuid())\n  name                String?\n  email               String        @unique\n  emailVerified       DateTime?\n  image               String?\n  password            String?\n  // `role` SIGUE SIENDO la fuente de permisos mientras `perfilId` sea null.\n  // Es lo que permite introducir los perfiles sin migrar de golpe las decenas de\n  // comprobaciones por rol que ya existen: un usuario sin perfil se comporta\n  // exactamente igual que antes (ver PERMISOS_POR_ROL en src/lib/auth/permisos.ts).\n  role                UserRole      @default(EMPLEADO)\n  activo              Boolean       @default(true)\n  // Perfil de acceso. Cuando está presente, MANDA sobre `role`.\n  perfilId            String?\n  perfil              PerfilAcceso? @relation(fields: [perfilId], references: [id])\n  // Sucursales visibles cuando el alcance del perfil es SUCURSAL. Vacío con\n  // alcance SUCURSAL = no ve ninguna, que es el fallo seguro.\n  sucursalesIds       String[]      @default([])\n  // Se activa al crear el usuario y al resetear su contraseña: la clave temporal\n  // que fija un administrador no puede quedarse como definitiva.\n  debeCambiarPassword Boolean       @default(false)\n  passwordCambiadaAt  DateTime?\n  ultimoAcceso        DateTime?\n  createdAt           DateTime      @default(now())\n  updatedAt           DateTime      @updatedAt\n\n  empleado         Empleado?\n  sessions         Session[]\n  accounts         Account[]\n  lotesImportacion LoteImportacion[]\n\n  @@index([perfilId])\n}\n\n/**\n * Alcance de DATOS: sobre QUIÉNES actúa un permiso.\n * El eje de acciones (`empleados.editar`) y el de filas son independientes: un\n * supervisor y una jefa de RRHH pueden compartir el permiso de ver empleados y\n * aun así deber ver plantillas distintas. Sin este segundo eje, «granular»\n * significa sólo «qué botones aparecen».\n */\nenum AlcanceDatos {\n  TODO // toda la empresa\n  SUCURSAL // sólo las sucursales asignadas al usuario\n  DEPARTAMENTO // sólo el departamento del empleado vinculado\n  PROPIO // sólo su propio expediente\n}\n\n/**\n * Perfil de acceso: un conjunto de permisos con nombre, reutilizable.\n * Los permisos se guardan como códigos `modulo.accion` (ver el catálogo en\n * src/lib/auth/permisos.ts). Un array de texto en vez de una tabla puente porque\n * el catálogo es una constante del código, no un dato que administre el usuario:\n * una tabla `Permiso` exigiría mantener sincronizadas filas y constantes sin\n * ganar nada — y el nombre `Permiso` ya está tomado por los permisos LABORALES\n * (vacaciones, enfermedad), que son otra cosa completamente distinta.\n */\nmodel PerfilAcceso {\n  id                String       @id @default(cuid())\n  codigo            String       @unique\n  nombre            String\n  descripcion       String?\n  permisos          String[]     @default([])\n  /**\n   * Catálogo de permisos que EXISTÍA la última vez que se guardó este perfil.\n   * Es lo que distingue «no tiene este permiso porque alguien se lo quitó» de\n   * «no lo tiene porque no existía cuando se configuró». Sin esa distinción, al\n   * añadir un permiso al catálogo el módulo queda invisible para los perfiles ya\n   * creados y nadie relaciona una cosa con la otra; y refrescarlos a lo bruto\n   * revertiría la configuración del administrador.\n   * Vacío = perfil anterior a esta columna: se completa hasta su línea base la\n   * primera vez, y a partir de ahí la comparación es exacta.\n   */\n  permisosConocidos String[]     @default([])\n  alcance           AlcanceDatos @default(TODO)\n  // Los perfiles de sistema se pueden asignar pero no editar ni borrar: son la\n  // red de seguridad para no dejar la instalación sin un perfil administrador.\n  esSistema         Boolean      @default(false)\n  activo            Boolean      @default(true)\n  createdAt         DateTime     @default(now())\n  updatedAt         DateTime     @updatedAt\n\n  usuarios User[]\n}\n\nenum TipoImportacion {\n  EMPLEADOS\n  DEDUCCIONES\n  HORAS_EXTRA\n  HORARIOS\n}\n\nenum EstadoLote {\n  VALIDADO // pasó la validación y espera confirmación\n  APLICADO\n  RECHAZADO // tenía errores bloqueantes\n  CANCELADO\n  EXPIRADO\n}\n\n/**\n * Lote de importación: el resultado de validar un archivo, a la espera de que\n * alguien lo confirme.\n * POR QUÉ EN LA BASE Y NO EN MEMORIA: la importación es en dos fases (validar →\n * confirmar) y entre una y otra puede pasar cualquier cosa. Un caché en memoria\n * se pierde al reiniciar y no existe para la otra instancia detrás del balanceador,\n * de modo que el usuario confirmaría contra un lote que ya no está. Guardarlo\n * además deja historial: quién subió qué archivo, con qué resultado y cuándo.\n */\nmodel LoteImportacion {\n  id              String          @id @default(cuid())\n  tipo            TipoImportacion\n  estado          EstadoLote      @default(VALIDADO)\n  nombreArchivo   String\n  // Filas ya normalizadas y validadas, listas para escribir. Se guardan tal cual\n  // se validaron: si el archivo cambia entre fase y fase, se aplica lo que se\n  // revisó, no lo que haya subido después.\n  filas           Json\n  // Errores y advertencias por número de línea, para reconstruir la vista previa.\n  incidencias     Json\n  totalFilas      Int             @default(0)\n  totalCrear      Int             @default(0)\n  totalActualizar Int             @default(0)\n  totalErrores    Int             @default(0)\n  // Un lote sin confirmar caduca: evita aplicar semanas después un archivo\n  // validado contra un estado de la base que ya no existe.\n  expiraEn        DateTime\n  aplicadoEn      DateTime?\n  resultado       Json?\n  usuarioId       String?\n  usuario         User?           @relation(fields: [usuarioId], references: [id])\n  usuarioEmail    String?\n  createdAt       DateTime        @default(now())\n  updatedAt       DateTime        @updatedAt\n\n  @@index([tipo, estado])\n  @@index([usuarioId, createdAt])\n}\n\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String? @db.Text\n  access_token      String? @db.Text\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String? @db.Text\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\n// ─── EMPLEADOS ────────────────────────────────────────────────────────────────\n\nmodel Empleado {\n  id                 String         @id @default(cuid())\n  codigo             String         @unique\n  // Datos personales\n  primerNombre       String\n  segundoNombre      String?\n  primerApellido     String\n  segundoApellido    String?\n  fechaNacimiento    DateTime\n  genero             String\n  estadoCivil        String?\n  nacionalidad       String         @default(\"Hondureño\")\n  identidad          String?        @unique\n  rtn                String?\n  ihssNro            String?\n  rapNro             String?\n  telefonoPersonal   String?\n  telefonoEmergencia String?\n  contactoEmergencia String?\n  direccion          String?\n  fotoPerfil         String?\n  // Datos laborales\n  fechaIngreso       DateTime\n  fechaSalida        DateTime?\n  estado             EstadoEmpleado @default(ACTIVO)\n  tipoContrato       TipoContrato   @default(INDEFINIDO)\n  salarioBase        Decimal        @db.Decimal(12, 2)\n  salarioDiario      Decimal?       @db.Decimal(12, 2)\n  salarioHora        Decimal?       @db.Decimal(12, 2)\n  tipoPlanilla       TipoPlanilla   @default(MENSUAL)\n  cuentaBancaria     String?\n  banco              String?\n  // Relaciones organizacionales\n  sucursalId         String\n  sucursal           Sucursal       @relation(fields: [sucursalId], references: [id])\n  departamentoId     String\n  departamento       Departamento   @relation(fields: [departamentoId], references: [id])\n  puestoId           String?\n  puesto             Puesto?        @relation(fields: [puestoId], references: [id])\n  supervisorId       String? // jefe directo\n  supervisor         Empleado?      @relation(\"SupervisorSubordinados\", fields: [supervisorId], references: [id])\n  /**\n   * Centro de costo PROPIO, que prevalece sobre el del departamento.\n   * Existe para el caso real que rompe la regla: alguien adscrito a Ingeniería\n   * cuyo coste se carga a un proyecto o a otra área. Vacío = hereda el del\n   * departamento, que es lo habitual.\n   */\n  centroCostoId      String?\n  centroCosto        CentroCosto?   @relation(fields: [centroCostoId], references: [id])\n  /**\n   * Datos de DIRECTORIO. Separados de los personales a propósito: el correo y la\n   * extensión corporativos son información de contacto laboral, no dato privado,\n   * y por eso no van detrás del permiso de datos personales como el teléfono.\n   */\n  emailCorporativo   String?\n  extension          String?\n  /**\n   * Correo PERSONAL. Dato privado —va con el teléfono personal, detrás de\n   * `empleados.pii`—, a diferencia del corporativo, que es de directorio. Existe\n   * porque la mayoría de operarios no tiene correo de empresa, y los comprobantes\n   * de pago sólo llegaban a quien tenía una cuenta de usuario en el sistema.\n   */\n  emailPersonal      String?\n  /**\n   * IHSS MENSUAL fijo pactado para esta persona. Si tiene valor, reemplaza la\n   * parte del empleado calculada por porcentaje (la patronal sigue por\n   * porcentaje). Vacío = cálculo normal. Ver `calcularIHSS`.\n   */\n  ihssMontoFijo      Decimal?       @db.Decimal(12, 2)\n  userId             String?        @unique\n  user               User?          @relation(fields: [userId], references: [id])\n  createdAt          DateTime       @default(now())\n  updatedAt          DateTime       @updatedAt\n\n  contratos            Contrato[]\n  permisos             Permiso[]\n  marcajes             Marcaje[]\n  eventosBiometricos   MarcajeEvento[]\n  pinesBiometricos     EmpleadoPin[]\n  deducciones          DeduccionEmpleado[]\n  planillasDetalle     PlanillaDetalle[]\n  evaluaciones         Evaluacion[]\n  documentos           Documento[]\n  historialSalarios    HistorialSalario[]\n  portalPosts          PortalPost[]\n  anuncios             Anuncio[]\n  subordinados         Empleado[]                 @relation(\"SupervisorSubordinados\")\n  evaluacionesComoEval EvaluacionParticipante[]   @relation(\"EvaluadorParticipante\")\n  dotaciones           AsignacionDotacion[]\n  capacitaciones       ParticipanteCapacitacion[]\n  liquidacionesDecimo  LiquidacionDecimo[]\n  liquidacionesFinales LiquidacionFinal[]\n  anticiposPrestacion  AnticipoPrestacion[]\n  documentosEmitidos   DocumentoEmitido[]\n  solicitudesPrestamo  SolicitudPrestamo[]\n  incapacidades        Incapacidad[]\n  asignacionesTurno    AsignacionTurno[]\n  preferenciaHorario   PreferenciaHorario?\n  horarioDias          HorarioDia[]\n  trasladosTemporales  TrasladoTemporal[]\n  vistasMaterial       VistaMaterial[]\n  acumuladosIsr        AcumuladoIsr[]\n  basesRap             BaseRapMes[]\n  fichaMedica          FichaMedica?\n  familiares           FamiliarEmpleado[]\n  beneficiarios        BeneficiarioEmpleado[]\n\n  // El organigrama y el filtro de \"mi equipo\" recorren esta columna en cada carga.\n  @@index([supervisorId])\n  @@index([centroCostoId])\n}\n\nmodel Contrato {\n  id            String       @id @default(cuid())\n  empleadoId    String\n  empleado      Empleado     @relation(fields: [empleadoId], references: [id])\n  tipoContrato  TipoContrato\n  fechaInicio   DateTime\n  fechaFin      DateTime?\n  salario       Decimal      @db.Decimal(12, 2)\n  cargo         String\n  jornada       String?\n  horario       String?\n  observaciones String?      @db.Text\n  activo        Boolean      @default(true)\n  archivoUrl    String?\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n}\n\nmodel HistorialSalario {\n  id              String   @id @default(cuid())\n  empleadoId      String\n  empleado        Empleado @relation(fields: [empleadoId], references: [id])\n  salarioAnterior Decimal  @db.Decimal(12, 2)\n  salarioNuevo    Decimal  @db.Decimal(12, 2)\n  fechaCambio     DateTime\n  motivo          String?\n  tipo            String   @default(\"INDIVIDUAL\") // INDIVIDUAL | COLECTIVO\n  // Atribución del cambio. Sin esto el historial registra QUÉ cambió y CUÁNDO,\n  // pero nunca QUIÉN — que es lo primero que pide una auditoría externa y lo\n  // que distingue un aumento autorizado de uno que no lo fue.\n  usuarioId       String?\n  usuarioEmail    String?\n  createdAt       DateTime @default(now())\n\n  @@index([empleadoId, fechaCambio])\n}\n\n// ─── ASISTENCIA Y MARCAJES ────────────────────────────────────────────────────\n\nmodel Marcaje {\n  id                 String    @id @default(cuid())\n  empleadoId         String\n  empleado           Empleado  @relation(fields: [empleadoId], references: [id])\n  fecha              DateTime  @db.Date\n  horaEntrada        DateTime?\n  horaSalida         DateTime?\n  horasNormales      Decimal   @default(0) @db.Decimal(5, 2)\n  // Total de horas extraordinarias del día. Debe ser la SUMA del desglose de\n  // abajo; se conserva para no romper reportes ni integraciones existentes.\n  horasExtra         Decimal   @default(0) @db.Decimal(5, 2)\n  // Desglose por jornada — Art. 330 C.T. Cada jornada lleva un recargo distinto\n  // (25 % / 50 % / 75 %), así que sin este desglose es imposible liquidar la\n  // hora extra correctamente: antes todas se pagaban como diurnas.\n  horasExtraDiurna   Decimal   @default(0) @db.Decimal(5, 2)\n  horasExtraMixta    Decimal   @default(0) @db.Decimal(5, 2)\n  horasExtraNocturna Decimal   @default(0) @db.Decimal(5, 2)\n  // Horas trabajadas en día feriado o de descanso semanal (Art. 339: al doble).\n  horasFeriado       Decimal   @default(0) @db.Decimal(5, 2)\n  // Almuerzo u otra pausa descontada del lapso entre entrada y salida: no es\n  // tiempo de trabajo. Se guarda para poder explicar la diferencia entre lo que\n  // estuvo la persona en la empresa y las horas que se le pagan.\n  minutosDescanso    Int       @default(0)\n  esAusencia         Boolean   @default(false)\n  esDiaLibre         Boolean   @default(false)\n  observacion        String?\n  fuente             String    @default(\"BIOMETRICO\") // BIOMETRICO | MANUAL | PLANTILLA\n  dispositivoId      String?\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n\n  @@unique([empleadoId, fecha])\n  @@index([fecha])\n}\n\n/// Calendario de feriados nacionales y asuetos de empresa.\n/// Sin él, el trabajo en día feriado se pagaba como jornada ordinaria.\nmodel Feriado {\n  id         String   @id @default(cuid())\n  fecha      DateTime @db.Date\n  nombre     String\n  /// `null` = aplica a toda la empresa; con valor, sólo a esa sucursal\n  /// (permite asuetos locales como la feria patronal del municipio).\n  sucursalId String?\n  esNacional Boolean  @default(true)\n  activo     Boolean  @default(true)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@unique([fecha, sucursalId])\n  @@index([fecha])\n}\n\nmodel DispositivoBiometrico {\n  id              String          @id @default(cuid())\n  nombre          String\n  /// ZKTeco y Hikvision no comparten NADA: protocolo binario en TCP 4370 el\n  /// primero, HTTP+JSON (ISAPI) con Digest auth el segundo. Sin este campo no\n  /// hay forma de elegir el driver.\n  marca           MarcaBiometrico @default(ZKTECO)\n  modelo          String?\n  /// Número de serie que reporta el equipo. Identifica al dispositivo con\n  /// independencia de que le cambien la IP.\n  serie           String?         @unique\n  ip              String\n  puerto          Int             @default(4370)\n  /// Hikvision exige credenciales en cada petición ISAPI (HTTP Digest). Se\n  /// guarda cifrada — ver lib/seguridad/cifrado.ts. ZKTeco no las usa.\n  usuario         String?\n  passwordCifrado String?\n  /// Desfase de la hora de pared del equipo respecto a UTC. Honduras es UTC−6\n  /// fijo y sin horario de verano, de ahí el valor por omisión. Se guarda como\n  /// minutos en vez de un nombre IANA porque sin DST no hace falta más, y así\n  /// la conversión no depende de la zona del proceso ni de una librería.\n  offsetMinutos   Int             @default(-360)\n  sucursalId      String?\n  activo          Boolean         @default(true)\n  ultimaSync      DateTime?\n  /// Marca de agua alta: instante del evento más reciente ya ingerido. Permite\n  /// pedirle al equipo sólo lo nuevo en vez de releer todo el buffer.\n  ultimoEventoEn  DateTime?\n  createdAt       DateTime        @default(now())\n  updatedAt       DateTime        @updatedAt\n\n  eventos MarcajeEvento[]\n  pines   EmpleadoPin[]\n}\n\nenum MarcaBiometrico {\n  ZKTECO\n  HIKVISION\n}\n\n/// Qué es una marca: entrada, salida, o todavía no se sabe.\n///\n/// DESCONOCIDO no es un caso raro, es el caso NORMAL en ZKTeco: `getAttendances()`\n/// devuelve un timestamp pelado, sin bandera de entrada/salida. El tipo se\n/// resuelve al agregar el día, ordenando las marcas.\nenum TipoMarca {\n  ENTRADA\n  SALIDA\n  DESCONOCIDO\n}\n\nenum EstadoEvento {\n  /// Ingerido, pendiente de agregarse a un Marcaje.\n  PENDIENTE\n  /// Ya contribuyó al Marcaje de su día.\n  PROCESADO\n  /// El PIN no corresponde a ningún empleado. NO se descarta: espera a que\n  /// alguien lo asigne, y entonces se reprocesa.\n  CUARENTENA\n  /// Descartado con motivo (fuera de rango, dispositivo dado de baja…).\n  DESCARTADO\n}\n\n/// Marcación cruda tal como la emitió el reloj, antes de convertirse en jornada.\n///\n/// POR QUÉ EXISTE UNA TABLA APARTE. `Marcaje` es un AGREGADO DIARIO: una fila por\n/// empleado y día, con una entrada y una salida. Un reloj no emite eso; emite N\n/// eventos sueltos. Escribirlos directamente sobre `Marcaje` perdía cuatro cosas\n/// que no se pueden reconstruir después:\n///\n///   1. Idempotencia — los equipos reenvían lotes cuando no reciben confirmación.\n///      La clave única de abajo hace que releer el buffer no duplique nada.\n///   2. Auditoría — ante un reclamo hay que poder mostrar «el reloj reportó estas\n///      marcas y el sistema calculó estas horas».\n///   3. Recálculo — si se registra un feriado DESPUÉS de procesar la asistencia,\n///      hay que rehacer el día; sin los crudos no hay de dónde.\n///   4. Almuerzo y turnos partidos — cuatro marcas colapsadas a primera/última\n///      le regalan la hora de almuerzo al empleado.\nmodel MarcajeEvento {\n  id            String                @id @default(cuid())\n  dispositivoId String\n  dispositivo   DispositivoBiometrico @relation(fields: [dispositivoId], references: [id], onDelete: Cascade)\n  /// Correlativo del propio equipo, tal cual lo reporta. NO es `Empleado.codigo`.\n  pin           String\n  /// Resuelto vía EmpleadoPin. `null` mientras está en cuarentena.\n  empleadoId    String?\n  empleado      Empleado?             @relation(fields: [empleadoId], references: [id], onDelete: SetNull)\n  /// Instante real de la marca.\n  ocurridoEn    DateTime\n  /// Día laboral al que se imputa, como fecha de CALENDARIO (medianoche UTC),\n  /// que es la convención de `Marcaje.fecha`. Ver la doctrina en lib/utils.ts.\n  fechaLocal    DateTime              @db.Date\n  tipo          TipoMarca             @default(DESCONOCIDO)\n  estado        EstadoEvento          @default(PENDIENTE)\n  /// Modo de verificación si el equipo lo informa (huella, rostro, tarjeta).\n  verificacion  String?\n  /// Registro original del equipo, para poder auditar sin volver a consultarlo.\n  crudo         Json?\n  motivo        String?\n  procesadoEn   DateTime?\n  createdAt     DateTime              @default(now())\n\n  /// CLAVE DE IDEMPOTENCIA. Un mismo equipo no puede reportar dos veces la misma\n  /// persona en el mismo instante; si lo hace, es un reenvío.\n  @@unique([dispositivoId, pin, ocurridoEn])\n  @@index([estado, fechaLocal])\n  @@index([empleadoId, fechaLocal])\n  @@index([dispositivoId, pin])\n}\n\n/// Vínculo entre el correlativo de un reloj y un empleado de la nómina.\n///\n/// POR QUÉ NO ES UN CAMPO EN `Empleado`. Los equipos numeran a sus usuarios\n/// desde 1 cada uno. Con dos sucursales, el PIN 1 del reloj de Tegucigalpa y el\n/// PIN 1 del de San Pedro son personas distintas, así que un `pinBiometrico`\n/// único global mapearía mal en cuanto haya un segundo equipo — y `Dispositivo-\n/// Biometrico` ya contempla varios, porque tiene `sucursalId`. La unicidad que\n/// corresponde es por dispositivo.\nmodel EmpleadoPin {\n  id            String                @id @default(cuid())\n  empleadoId    String\n  empleado      Empleado              @relation(fields: [empleadoId], references: [id], onDelete: Cascade)\n  dispositivoId String\n  dispositivo   DispositivoBiometrico @relation(fields: [dispositivoId], references: [id], onDelete: Cascade)\n  pin           String\n  createdAt     DateTime              @default(now())\n  updatedAt     DateTime              @updatedAt\n\n  /// Un PIN identifica a UNA persona dentro de UN equipo.\n  @@unique([dispositivoId, pin])\n  @@index([empleadoId])\n}\n\n// ─── PERMISOS Y VACACIONES ───────────────────────────────────────────────────\n\nmodel Permiso {\n  id              String      @id @default(cuid())\n  empleadoId      String\n  empleado        Empleado    @relation(fields: [empleadoId], references: [id])\n  tipo            TipoPermiso\n  fechaInicio     DateTime    @db.Date\n  fechaFin        DateTime    @db.Date\n  diasSolicitados Int\n  diasAprobados   Int?\n  motivo          String?     @db.Text\n  estado          String      @default(\"PENDIENTE\") // PENDIENTE | APROBADO | RECHAZADO\n  aprobadoPor     String?\n  observacion     String?\n  createdAt       DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n}\n\nmodel SaldoVacaciones {\n  id              String   @id @default(cuid())\n  empleadoId      String   @unique\n  diasDisponibles Decimal  @default(0) @db.Decimal(5, 2)\n  diasTomados     Decimal  @default(0) @db.Decimal(5, 2)\n  anio            Int\n  updatedAt       DateTime @updatedAt\n}\n\n// ─── DEDUCCIONES ──────────────────────────────────────────────────────────────\n\nmodel TipoDeduccionConfig {\n  id                  String               @id @default(cuid())\n  nombre              String\n  codigo              String               @unique\n  tipo                TipoDeduccion\n  porcentaje          Decimal?             @db.Decimal(5, 4) // p.ej. 0.025 = 2.5%\n  /// Cómo se calculan IHSS, IVM, RAP e INFOP: por porcentaje del salario o como\n  /// monto fijo mensual igual para todos. Lo decide el administrador en\n  /// Configuración → Parámetros de ley. El resto de tipos no lo usa.\n  modo                ModoCalculoDeduccion @default(PORCENTAJE)\n  /// Monto fijo MENSUAL del empleado (con `modo = MONTO_FIJO`).\n  montoFijo           Decimal?             @db.Decimal(12, 2)\n  /// Monto fijo MENSUAL patronal (con `modo = MONTO_FIJO`).\n  montoFijoEmpleador  Decimal?             @db.Decimal(12, 2)\n  aplicaEmpleado      Boolean              @default(true)\n  aplicaEmpleador     Boolean              @default(false)\n  porcentajeEmpleador Decimal?             @db.Decimal(5, 4)\n  topeMaximo          Decimal?             @db.Decimal(12, 2)\n  // Piso de la base cotizable. RAP: la base es el EXCEDENTE sobre este valor.\n  topeMinimo          Decimal?             @db.Decimal(12, 2)\n  activo              Boolean              @default(true)\n  esLegal             Boolean              @default(false)\n  descripcion         String?\n  createdAt           DateTime             @default(now())\n  updatedAt           DateTime             @updatedAt\n\n  deduccionesEmpleado DeduccionEmpleado[]\n}\n\nmodel DeduccionEmpleado {\n  id              String              @id @default(cuid())\n  empleadoId      String\n  empleado        Empleado            @relation(fields: [empleadoId], references: [id])\n  tipoDeduccionId String\n  tipoDeduccion   TipoDeduccionConfig @relation(fields: [tipoDeduccionId], references: [id])\n  monto           Decimal             @db.Decimal(12, 2)\n  cuotasMeses     Int?\n  cuotasPagadas   Int                 @default(0)\n  saldo           Decimal?            @db.Decimal(12, 2)\n  fechaInicio     DateTime            @db.Date\n  fechaFin        DateTime?           @db.Date\n  activo          Boolean             @default(true)\n  observacion     String?\n  createdAt       DateTime            @default(now())\n  updatedAt       DateTime            @updatedAt\n\n  amortizaciones AmortizacionPlanilla[]\n  solicitud      SolicitudPrestamo?\n\n  // Se consulta una vez por empleado en cada cálculo de planilla.\n  @@index([empleadoId, activo])\n}\n\n// ─── PLANILLAS ────────────────────────────────────────────────────────────────\n\nmodel Planilla {\n  id               String         @id @default(cuid())\n  empresaId        String\n  empresa          Empresa        @relation(fields: [empresaId], references: [id])\n  // Sucursal cubierta por la planilla. `null` = planilla de toda la empresa.\n  // Sin este campo era imposible saber a cuál de las 13 sucursales correspondía\n  // una planilla, ni conciliar por sucursal, ni impedir duplicados por sucursal.\n  sucursalId       String?\n  sucursal         Sucursal?      @relation(fields: [sucursalId], references: [id])\n  // Alcance más fino dentro de la sucursal: sólo una división, o sólo un\n  // departamento. `null` = toda la sucursal (o toda la división). La cadena\n  // empresa → sucursal → división → departamento se valida al crearla.\n  divisionId       String?\n  division         Division?      @relation(fields: [divisionId], references: [id], onDelete: Restrict)\n  departamentoId   String?\n  departamento     Departamento?  @relation(fields: [departamentoId], references: [id], onDelete: Restrict)\n  tipo             TipoPlanilla\n  estado           EstadoPlanilla @default(BORRADOR)\n  fechaInicio      DateTime       @db.Date\n  fechaFin         DateTime       @db.Date\n  fechaPago        DateTime?      @db.Date\n  totalBruto       Decimal        @default(0) @db.Decimal(14, 2)\n  totalDeducciones Decimal        @default(0) @db.Decimal(14, 2)\n  totalNeto        Decimal        @default(0) @db.Decimal(14, 2)\n  totalEmpleador   Decimal        @default(0) @db.Decimal(14, 2)\n  observaciones    String?        @db.Text\n  aprobadoPor      String?\n  // ─── Blindaje de planilla cerrada ───────────────────────────────────────────\n  // Momento en que la planilla pasó a un estado cerrado (APROBADA/PAGADA).\n  cerradaAt        DateTime?\n  // SHA-256 del set de detalles al momento del cierre. Permite detectar\n  // cualquier alteración posterior de los montos ya aprobados.\n  hashCalculo      String?\n  pagadoPor        String?\n  anuladaPor       String?\n  motivoAnulacion  String?        @db.Text\n  createdAt        DateTime       @default(now())\n  updatedAt        DateTime       @updatedAt\n\n  detalles       PlanillaDetalle[]\n  amortizaciones AmortizacionPlanilla[]\n  enviosSap      SapEnvioAsiento[]\n\n  @@index([estado])\n  // La UNICIDAD del período NO se declara aquí: requiere ser un índice PARCIAL\n  // (excluye ANULADA, para poder reemitir un período corregido) y tratar\n  // `sucursalId`, `divisionId` y `departamentoId` NULL como valores comparables —\n  // dos cosas que Prisma no puede expresar. Vive en\n  // `prisma/sql/01-planilla-periodo-unico.sql` y se aplica con\n  // `npm run db:constraints` DESPUÉS de cada `db push`. Que dos alcances\n  // DISTINTOS no paguen dos veces a la misma persona lo impide la API al crear.\n  @@index([empresaId, sucursalId, tipo, fechaInicio, fechaFin])\n}\n\nmodel PlanillaDetalle {\n  id                  String        @id @default(cuid())\n  planillaId          String\n  planilla            Planilla      @relation(fields: [planillaId], references: [id])\n  empleadoId          String\n  empleado            Empleado      @relation(fields: [empleadoId], references: [id])\n  /**\n   * Dónde estaba la persona CUANDO se le pagó. Los reportes agrupan por aquí y\n   * no por su ubicación actual, para que un período cerrado no se reacomode si\n   * después cambia de área. Las líneas anteriores a estas columnas quedan en\n   * null y se agrupan por la ubicación actual del empleado.\n   */\n  sucursalId          String?\n  sucursal            Sucursal?     @relation(fields: [sucursalId], references: [id], onDelete: Restrict)\n  divisionId          String?\n  division            Division?     @relation(fields: [divisionId], references: [id], onDelete: Restrict)\n  departamentoId      String?\n  departamento        Departamento? @relation(fields: [departamentoId], references: [id], onDelete: Restrict)\n  /// El puesto al pagarse, como TEXTO: el comprobante muestra el de ese período aunque\n  /// después cambie, se renombre o se borre. Null en líneas calculadas antes del\n  /// 2026-11-14: el comprobante cae al puesto actual del empleado.\n  puesto              String?\n  // Ingresos\n  salarioBase         Decimal       @db.Decimal(12, 2)\n  diasTrabajados      Decimal       @default(0) @db.Decimal(5, 2)\n  horasExtra          Decimal       @default(0) @db.Decimal(5, 2)\n  montoHorasExtra     Decimal       @default(0) @db.Decimal(12, 2)\n  bonificaciones      Decimal       @default(0) @db.Decimal(12, 2)\n  otrosIngresos       Decimal       @default(0) @db.Decimal(12, 2)\n  totalBruto          Decimal       @default(0) @db.Decimal(12, 2)\n  // Deducciones empleado\n  ihssEmpleado        Decimal       @default(0) @db.Decimal(12, 2) // TOTAL empleado EM+IVM\n  rapEmpleado         Decimal       @default(0) @db.Decimal(12, 2)\n  afpEmpleado         Decimal       @default(0) @db.Decimal(12, 2)\n  isr                 Decimal       @default(0) @db.Decimal(12, 2)\n  /// Cómo se llegó al ISR de esta línea cuando se usó el CÁLCULO PERSONALIZADO\n  /// (ingreso anual proyectado, deducciones, ISR anual, lo ya retenido y los\n  /// períodos restantes). Null = método estándar. Lo lee el reporte DMR y queda\n  /// como rastro aunque después cambie la configuración.\n  isrDetalle          Json?\n  impuestoVecinal     Decimal       @default(0) @db.Decimal(12, 2)\n  cooperativa         Decimal       @default(0) @db.Decimal(12, 2)\n  prestamos           Decimal       @default(0) @db.Decimal(12, 2)\n  adelantos           Decimal       @default(0) @db.Decimal(12, 2)\n  ausencias           Decimal       @default(0) @db.Decimal(12, 2)\n  /// Días de incapacidad a cargo del IHSS en el período (del 4.º en adelante).\n  diasIncapacidadIhss Int           @default(0)\n  /// Salario que el patrono deja de pagar por esos días; el IHSS paga el subsidio al trabajador.\n  incapacidad         Decimal       @default(0) @db.Decimal(12, 2)\n  otrosDeducciones    Decimal       @default(0) @db.Decimal(12, 2)\n  totalDeducciones    Decimal       @default(0) @db.Decimal(12, 2)\n  // Aportaciones empleador\n  ihssEmpleador       Decimal       @default(0) @db.Decimal(12, 2) // TOTAL patronal EM+IVM\n  rapEmpleador        Decimal       @default(0) @db.Decimal(12, 2)\n  infop               Decimal       @default(0) @db.Decimal(12, 2)\n  /// Aporte patronal al Fondo de Reserva Laboral del RAP (Decreto 47-2024).\n  reservaLaboral      Decimal       @default(0) @db.Decimal(12, 2)\n  // Desglose IHSS régimen IVM (Invalidez, Vejez y Muerte)\n  ivmEmpleado         Decimal       @default(0) @db.Decimal(12, 2)\n  ivmEmpleador        Decimal       @default(0) @db.Decimal(12, 2)\n  ivmEstado           Decimal       @default(0) @db.Decimal(12, 2)\n  /// El IHSS del empleado salió de su monto fijo, no del porcentaje. Se guarda\n  /// en la planilla —no se consulta en la ficha— porque la boleta de un período\n  /// cerrado debe seguir diciendo lo que se aplicó aunque después se cambie.\n  ihssFijo            Boolean       @default(false)\n  // Resultado\n  salarioNeto         Decimal       @default(0) @db.Decimal(12, 2)\n  // Provisiones\n  provision13vo       Decimal       @default(0) @db.Decimal(12, 2)\n  provision14vo       Decimal       @default(0) @db.Decimal(12, 2)\n  provisionVacaciones Decimal       @default(0) @db.Decimal(12, 2)\n  // Control\n  emailEnviado        Boolean       @default(false)\n  emailEnviadoAt      DateTime?\n  createdAt           DateTime      @default(now())\n  updatedAt           DateTime      @updatedAt\n\n  @@unique([planillaId, empleadoId])\n  // El @@unique de arriba sólo sirve para buscar por planilla (es su primera\n  // columna). `/api/mis-boletas` filtra por empleado y hacía escaneo completo.\n  @@index([empleadoId])\n}\n\n/// Ingresos e ISR de un mes pagado FUERA de NominaHN (típicamente, los meses del\n/// año anteriores a empezar a usarlo), importados de la hoja «Retención en la\n/// fuente». Los usa el CÁLCULO PERSONALIZADO del ISR, que proyecta el año con lo\n/// realmente pagado y descuenta lo ya retenido. Si un mes está aquí, las líneas\n/// de planilla de ese mes no se cuentan, para no sumarlo dos veces.\nmodel AcumuladoIsr {\n  id          String   @id @default(cuid())\n  empleadoId  String\n  empleado    Empleado @relation(fields: [empleadoId], references: [id], onDelete: Cascade)\n  anio        Int\n  /// 1 = enero … 12 = diciembre.\n  mes         Int\n  /// Salario ordinario efectivamente pagado en el mes.\n  sueldo      Decimal  @db.Decimal(12, 2)\n  /// Comisiones, horas extra, bonificaciones y otros ingresos del mes.\n  variables   Decimal  @default(0) @db.Decimal(12, 2)\n  isrRetenido Decimal  @default(0) @db.Decimal(12, 2)\n  /// IMPORTACION (desde la hoja) o MANUAL.\n  origen      String   @default(\"IMPORTACION\")\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@unique([empleadoId, anio, mes])\n  @@index([anio])\n}\n\n/// Base del RAP y de la Reserva Laboral importada para un mes, cuando se cotiza a\n/// MES VENCIDO (Parámetros de ley; ver `lib/payroll/rap-mes-vencido.ts`): lo devengado\n/// el mes ANTERIOR, comisiones incluidas. Reemplaza a la que el sistema saca de las\n/// planillas de ese mes. No es una deducción: por eso no va en DeduccionEmpleado,\n/// donde se vería como un descuento de toda la base.\nmodel BaseRapMes {\n  id         String   @id @default(cuid())\n  empleadoId String\n  empleado   Empleado @relation(fields: [empleadoId], references: [id], onDelete: Cascade)\n  /// Mes en que se DESCUENTA (la base es lo devengado el mes anterior). 1 = enero.\n  anio       Int\n  mes        Int\n  base       Decimal  @db.Decimal(12, 2)\n  /// IMPORTACION (plantilla de deducciones del período) o MANUAL.\n  origen     String   @default(\"IMPORTACION\")\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@unique([empleadoId, anio, mes])\n  @@index([anio, mes])\n}\n\n/// Registro de lo que CADA planilla amortizó de CADA deducción a plazo.\n///\n/// POR QUÉ EXISTE: el flujo de corrección del sistema es anular y reemitir. Sin\n/// este registro, al recalcular un período anulado las cuotas volvían a\n/// consumirse y el préstamo del trabajador se amortizaba de más, sin que nada\n/// lo detectara.\n///\n/// Se guarda el DELTA aplicado, no el estado previo. La reversión es entonces\n/// independiente del orden: si dos planillas cobraron cuotas de un mismo\n/// préstamo y se anula la primera, devolver su importe deja el saldo correcto\n/// aunque la segunda siga vigente. Restaurar un \"estado anterior\" habría\n/// pisado lo que la segunda cobró.\nmodel AmortizacionPlanilla {\n  id            String            @id @default(cuid())\n  planillaId    String\n  planilla      Planilla          @relation(fields: [planillaId], references: [id])\n  deduccionId   String\n  deduccion     DeduccionEmpleado @relation(fields: [deduccionId], references: [id])\n  /// Importe efectivamente cobrado. Al anular se devuelve al saldo.\n  montoAplicado Decimal           @db.Decimal(12, 2)\n  /// La deducción lleva columna `saldo`. Si es false, revertir no la toca.\n  llevaSaldo    Boolean           @default(true)\n  /// Fue ESTA amortización la que agotó la deducción y la desactivó.\n  desactivo     Boolean           @default(false)\n  /// Sellada al revertir. Impide devolver dos veces el mismo importe.\n  revertidaAt   DateTime?\n  createdAt     DateTime          @default(now())\n\n  // Una planilla amortiza una deducción a lo sumo una vez.\n  @@unique([planillaId, deduccionId])\n  @@index([deduccionId])\n  @@index([planillaId, revertidaAt])\n}\n\n// ─── DÉCIMO TERCER Y DÉCIMO CUARTO MES ────────────────────────────────────────\n\nenum TipoDecimo {\n  DECIMO_TERCERO // Aguinaldo — se paga en diciembre, devenga de enero a diciembre\n  DECIMO_CUARTO // Compensación educativa — se paga en junio, devenga de julio a junio\n}\n\nenum EstadoDecimo {\n  CALCULADA\n  PAGADA\n  ANULADA\n}\n\n/// Liquidación del 13.º y 14.º mes.\n///\n/// Antes sólo existía la PROVISIÓN mensual dentro de PlanillaDetalle, que es un\n/// apunte contable: no permitía consultar el acumulado de un empleado ni emitir\n/// el pago. Este modelo cierra ese ciclo y guarda la traza de cómo se calculó.\nmodel LiquidacionDecimo {\n  id              String       @id @default(cuid())\n  empleadoId      String\n  empleado        Empleado     @relation(fields: [empleadoId], references: [id])\n  tipo            TipoDecimo\n  anio            Int\n  /// Ventana de devengo efectivamente computada (acotada por ingreso y salida).\n  periodoDesde    DateTime     @db.Date\n  periodoHasta    DateTime     @db.Date\n  diasComputados  Int\n  /// Promedio de salario ordinario del período, base del cálculo.\n  salarioPromedio Decimal      @db.Decimal(12, 2)\n  montoDevengado  Decimal      @db.Decimal(12, 2)\n  /// Porción exenta de ISR (hasta diez salarios mínimos entre ambos décimos).\n  montoExento     Decimal      @default(0) @db.Decimal(12, 2)\n  montoGravado    Decimal      @default(0) @db.Decimal(12, 2)\n  isrRetenido     Decimal      @default(0) @db.Decimal(12, 2)\n  montoPagado     Decimal      @default(0) @db.Decimal(12, 2)\n  /// Adelantos de este décimo ya pagados aparte (AnticipoPrestacion): se restan del neto.\n  adelantos       Decimal      @default(0) @db.Decimal(12, 2)\n  estado          EstadoDecimo @default(CALCULADA)\n  /// Marca la liquidación proporcional emitida al terminar la relación laboral.\n  esProporcional  Boolean      @default(false)\n  fechaPago       DateTime?    @db.Date\n  observaciones   String?      @db.Text\n  calculadoPor    String?\n  pagadoPor       String?\n  createdAt       DateTime     @default(now())\n  updatedAt       DateTime     @updatedAt\n\n  anticipos AnticipoPrestacion[]\n\n  // Un empleado tiene una sola liquidación de cada décimo por año.\n  @@unique([empleadoId, tipo, anio])\n  @@index([anio, tipo, estado])\n}\n\nenum TipoAnticipoPrestacion {\n  /// Pago a cuenta de la cesantía: se rebaja del auxilio de cesantía al liquidar.\n  NEGOCIACION_PRESTACIONES\n  /// Adelanto del 13.º: se resta del décimo de ese año (o del proporcional al liquidar).\n  ADELANTO_DECIMO_TERCERO\n  /// Adelanto del 14.º: ídem, sobre el décimo cuarto del año de pago indicado.\n  ADELANTO_DECIMO_CUARTO\n}\n\nenum EstadoAnticipoPrestacion {\n  /// Pagado al empleado y todavía sin descontar.\n  VIGENTE\n  /// Ya rebajado de una liquidación final o de un décimo (ver montoAplicado).\n  APLICADO\n  ANULADO\n}\n\n/// Pagos hechos APARTE de la planilla (cheque o transferencia) a cuenta de prestaciones.\n///\n/// No son deducciones de planilla: no tocan el salario. La negociación de prestaciones se\n/// rebaja de la cesantía al liquidar, hasta dejarla en cero (el exceso se informa, no se\n/// cobra de otros conceptos); el adelanto de un décimo se resta al pagar ese décimo o, si\n/// el empleado sale antes, del décimo proporcional de su finiquito. Decisión de Edbin,\n/// 2026-11-14.\nmodel AnticipoPrestacion {\n  id                  String                   @id @default(cuid())\n  empleadoId          String\n  empleado            Empleado                 @relation(fields: [empleadoId], references: [id])\n  tipo                TipoAnticipoPrestacion\n  monto               Decimal                  @db.Decimal(12, 2)\n  fechaPago           DateTime                 @db.Date\n  /// Adelantos: año del PAGO del décimo (13.º en diciembre, 14.º en junio de ese año).\n  anioDecimo          Int?\n  /// Negociación: período de servicio que cubre (informativo).\n  periodoDesde        DateTime?                @db.Date\n  periodoHasta        DateTime?                @db.Date\n  /// Cheque, transferencia o documento con que se pagó.\n  referencia          String?\n  observacion         String?                  @db.Text\n  estado              EstadoAnticipoPrestacion @default(VIGENTE)\n  /// Lo que efectivamente se rebajó: menos que el monto si excedía la cesantía o el décimo.\n  montoAplicado       Decimal?                 @db.Decimal(12, 2)\n  liquidacionFinalId  String?\n  liquidacionFinal    LiquidacionFinal?        @relation(fields: [liquidacionFinalId], references: [id])\n  liquidacionDecimoId String?\n  liquidacionDecimo   LiquidacionDecimo?       @relation(fields: [liquidacionDecimoId], references: [id])\n  registradoPor       String?\n  motivoAnulacion     String?\n  createdAt           DateTime                 @default(now())\n  updatedAt           DateTime                 @updatedAt\n\n  @@index([empleadoId, tipo, estado])\n  @@index([tipo, anioDecimo, estado])\n}\n\n// ─── LIQUIDACIÓN FINAL DE PRESTACIONES ────────────────────────────────────────\n\n/// Causas de terminación que maneja la calculadora de la Secretaría de Trabajo.\nenum CausaTerminacion {\n  DESPIDO_INJUSTIFICADO\n  RENUNCIA\n  DESPIDO_JUSTIFICADO\n  MUERTE\n}\n\nenum EstadoLiquidacion {\n  BORRADOR\n  APROBADA\n  PAGADA\n  ANULADA\n}\n\n/// Finiquito de prestaciones al terminar la relación laboral.\n///\n/// Criterio: el de consulta.trabajo.gob.hn, que es el que aplica la inspectoría\n/// en un reclamo. El desglose por concepto se guarda en `conceptos` para que el\n/// documento sea reproducible aunque después cambien las tablas legales.\nmodel LiquidacionFinal {\n  id                 String            @id @default(cuid())\n  empleadoId         String\n  empleado           Empleado          @relation(fields: [empleadoId], references: [id])\n  causa              CausaTerminacion\n  fechaIngreso       DateTime          @db.Date\n  fechaSalida        DateTime          @db.Date\n  /// Empresa de hasta 10 trabajadores: tope de cesantía reducido y sin 35 %.\n  esMicroempresa     Boolean           @default(false)\n  /// Salario ordinario promedio de los últimos seis meses.\n  salarioPromedio    Decimal           @db.Decimal(12, 2)\n  salarioDiario      Decimal           @db.Decimal(12, 2)\n  diasServicio       Int\n  mesesServicio      Int\n  aniosServicio      Int\n  // Conceptos liquidados\n  preaviso           Decimal           @default(0) @db.Decimal(12, 2)\n  auxilioCesantia    Decimal           @default(0) @db.Decimal(12, 2)\n  vacaciones         Decimal           @default(0) @db.Decimal(12, 2)\n  decimoTercero      Decimal           @default(0) @db.Decimal(12, 2)\n  decimoCuarto       Decimal           @default(0) @db.Decimal(12, 2)\n  salariosPendientes Decimal           @default(0) @db.Decimal(12, 2)\n  otrosAdeudos       Decimal           @default(0) @db.Decimal(12, 2)\n  totalPrestaciones  Decimal           @default(0) @db.Decimal(12, 2)\n  deducciones        Decimal           @default(0) @db.Decimal(12, 2)\n  totalAPagar        Decimal           @default(0) @db.Decimal(12, 2)\n  /// Desglose completo tal y como se calculó, con su fundamento legal.\n  conceptos          Json?\n  /// Topes aplicados y derechos que no correspondían.\n  observaciones      String?           @db.Text\n  estado             EstadoLiquidacion @default(BORRADOR)\n  fechaPago          DateTime?         @db.Date\n  calculadoPor       String?\n  aprobadoPor        String?\n  /// Préstamos y adelantos de salario que este finiquito dio por saldados, con su saldo\n  /// ANTERIOR ([{ id, saldo, activo, observacion, cobrado }]): al anularlo se restituyen.\n  deudasSaldadas     Json?\n  createdAt          DateTime          @default(now())\n  updatedAt          DateTime          @updatedAt\n\n  anticipos AnticipoPrestacion[]\n\n  @@index([empleadoId])\n  @@index([estado])\n}\n\n// ─── EVALUACIONES ────────────────────────────────────────────────────────────\n\nmodel Evaluacion {\n  id             String             @id @default(cuid())\n  empleadoId     String\n  empleado       Empleado           @relation(fields: [empleadoId], references: [id])\n  tipo           TipoEvaluacion\n  estado         EstadoEvaluacion   @default(BORRADOR)\n  periodo        String // \"2024-01\", \"2024-T1\"\n  campanaId      String?\n  campana        EvaluacionCampana? @relation(fields: [campanaId], references: [id])\n  // Calificación consolidada (promedio ponderado de todos los evaluadores)\n  calificacion   Decimal            @default(0) @db.Decimal(5, 2)\n  // Dimensiones Nine-Box\n  desempeno      Decimal?           @db.Decimal(5, 2) // eje X\n  potencial      Decimal?           @db.Decimal(5, 2) // eje Y\n  comentarios    String?            @db.Text\n  fortalezas     String?            @db.Text\n  mejoras        String?            @db.Text\n  objetivos      String?            @db.Text\n  // Bono resultante\n  bonoPorcentaje Decimal?           @db.Decimal(5, 4) // 0.10 = 10%\n  bonoMonto      Decimal?           @db.Decimal(12, 2)\n  bonoAplicado   Boolean            @default(false)\n  fechaFirma     DateTime?\n  createdAt      DateTime           @default(now())\n  updatedAt      DateTime           @updatedAt\n\n  criterios     CriterioEvaluacion[]\n  participantes EvaluacionParticipante[]\n}\n\nmodel CriterioEvaluacion {\n  id             String                  @id @default(cuid())\n  evaluacionId   String\n  evaluacion     Evaluacion              @relation(fields: [evaluacionId], references: [id], onDelete: Cascade)\n  participanteId String? // null = promedio consolidado\n  participante   EvaluacionParticipante? @relation(fields: [participanteId], references: [id])\n  competenciaId  String?\n  competencia    CompetenciaDefinicion?  @relation(fields: [competenciaId], references: [id])\n  criterio       String // nombre del criterio si no está en catálogo\n  nivelRequerido Int? // 1-5 según NivelCompetencia\n  // 0-100: Decimal(5,2), porque con (4,2) un 100 desbordaba la columna.\n  calificacion   Decimal                 @default(0) @db.Decimal(5, 2)\n  peso           Decimal                 @default(1) @db.Decimal(4, 2)\n  comentario     String?\n}\n\n// Evaluadores asignados a una evaluación (360°: self, boss, peers)\nmodel EvaluacionParticipante {\n  id              String       @id @default(cuid())\n  evaluacionId    String\n  evaluacion      Evaluacion   @relation(fields: [evaluacionId], references: [id], onDelete: Cascade)\n  evaluadorId     String // empleadoId del evaluador\n  evaluador       Empleado     @relation(\"EvaluadorParticipante\", fields: [evaluadorId], references: [id])\n  rol             RolEvaluador\n  estado          String       @default(\"PENDIENTE\") // PENDIENTE | EN_PROGRESO | COMPLETADO\n  calificacion    Decimal?     @db.Decimal(5, 2)\n  comentarios     String?      @db.Text\n  fechaCompletado DateTime?\n  tokenAcceso     String?      @unique // token para link sin login\n  createdAt       DateTime     @default(now())\n  updatedAt       DateTime     @updatedAt\n\n  criteriosParticipante CriterioEvaluacion[]\n}\n\n// Catálogo de competencias organizacionales\nmodel CompetenciaDefinicion {\n  id             String          @id @default(cuid())\n  nombre         String\n  descripcion    String?         @db.Text\n  categoria      String          @default(\"CORE\") // CORE | LIDERAZGO | TECNICA | COMPORTAMIENTO\n  activa         Boolean         @default(true)\n  // Aspecto general: se evalúa a quien no tenga aspectos asignados en su puesto.\n  general        Boolean         @default(false)\n  // En qué evaluación se usa; null = en las dos.\n  tipoEvaluacion TipoEvaluacion?\n  // Peso como aspecto general; en un puesto manda el peso de PuestoCompetencia.\n  peso           Decimal         @default(1) @db.Decimal(4, 2)\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n\n  puestosCompetencia PuestoCompetencia[]\n  criterios          CriterioEvaluacion[]\n}\n\n// Matriz de competencias por puesto (niveles requeridos)\nmodel PuestoCompetencia {\n  id             String                @id @default(cuid())\n  puestoId       String\n  puesto         Puesto                @relation(fields: [puestoId], references: [id])\n  competenciaId  String\n  competencia    CompetenciaDefinicion @relation(fields: [competenciaId], references: [id])\n  nivelRequerido NivelCompetencia      @default(INTERMEDIO)\n  peso           Decimal               @default(1) @db.Decimal(4, 2) // peso en la evaluación\n  activa         Boolean               @default(true)\n  createdAt      DateTime              @default(now())\n\n  @@unique([puestoId, competenciaId])\n}\n\n// Campañas de evaluación (lanzamiento automático)\nmodel EvaluacionCampana {\n  id             String         @id @default(cuid())\n  nombre         String\n  tipo           TipoEvaluacion\n  estado         EstadoCampana  @default(PROGRAMADA)\n  periodo        String // \"2024-01\"\n  fechaInicio    DateTime\n  fechaFin       DateTime\n  // Cron: \"0 8 25 * *\" = día 25 de cada mes\n  cronExpression String?\n  // Configuración 360°\n  incluirAuto    Boolean        @default(true)\n  incluirJefe    Boolean        @default(true)\n  incluirPares   Boolean        @default(false)\n  incluirSubord  Boolean        @default(false)\n  // Sucursal / Depto scope (null = todos)\n  sucursalId     String?\n  departamentoId String?\n  emailEnviado   Boolean        @default(false)\n  recordatorioAt DateTime?\n  createdBy      String\n  createdAt      DateTime       @default(now())\n  updatedAt      DateTime       @updatedAt\n\n  evaluaciones Evaluacion[]\n}\n\n// Motor de bonos: rango de calificación → % bono\nmodel BonusConfig {\n  id              String         @id @default(cuid())\n  nombre          String\n  tipoEvaluacion  TipoEvaluacion\n  calificacionMin Decimal        @db.Decimal(5, 2)\n  calificacionMax Decimal        @db.Decimal(5, 2)\n  bonoPorcentaje  Decimal        @db.Decimal(5, 4) // 0.10 = 10% del salario\n  aplicarEn       String         @default(\"SIGUIENTE_PLANILLA\") // SIGUIENTE_PLANILLA | INMEDIATO\n  activo          Boolean        @default(true)\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n}\n\n// ─── PORTAL EMPLEADO ─────────────────────────────────────────────────────────\n\nmodel PortalPost {\n  id         String   @id @default(cuid())\n  titulo     String\n  contenido  String   @db.Text\n  categoria  String   @default(\"BLOG\") // BLOG | ANUNCIO\n  destacado  Boolean  @default(false)\n  activo     Boolean  @default(true)\n  autorId    String\n  autor      Empleado @relation(fields: [autorId], references: [id])\n  archivoUrl String?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n}\n\nmodel Anuncio {\n  id          String    @id @default(cuid())\n  titulo      String\n  contenido   String    @db.Text\n  urgente     Boolean   @default(false)\n  activo      Boolean   @default(true)\n  fechaExpira DateTime?\n  autorId     String\n  autor       Empleado  @relation(fields: [autorId], references: [id])\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n}\n\nmodel Documento {\n  id          String        @id @default(cuid())\n  empleadoId  String\n  empleado    Empleado      @relation(fields: [empleadoId], references: [id])\n  tipo        TipoDocumento\n  nombre      String\n  descripcion String?\n  archivoUrl  String\n  tamaño     Int?\n  createdAt   DateTime      @default(now())\n}\n\nmodel ContactoRRHH {\n  id        String   @id @default(cuid())\n  nombre    String\n  cargo     String\n  email     String?\n  telefono  String?\n  extension String?\n  foto      String?\n  activo    Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ─── CONFIGURACIÓN GENERAL ───────────────────────────────────────────────────\n\nmodel ConfiguracionSistema {\n  id          String   @id @default(cuid())\n  clave       String   @unique\n  valor       String   @db.Text\n  descripcion String?\n  updatedAt   DateTime @updatedAt\n}\n\n/// Cada respaldo hecho desde Configuración → Respaldos (ver `lib/respaldos/`):\n/// manual o automático, a qué destinos llegó y con qué resultado. La\n/// configuración (destinos, horario, claves cifradas) vive en\n/// ConfiguracionSistema «RESPALDOS_CONFIG».\nmodel Respaldo {\n  id              String    @id @default(cuid())\n  /// MANUAL o AUTOMATICO.\n  tipo            String\n  /// EN_CURSO, OK, PARCIAL (falló algún destino) o ERROR.\n  estado          String\n  archivo         String?\n  /// Bytes del archivo final.\n  tamano          BigInt?\n  /// Huella SHA-256 del archivo final, para comprobar una copia.\n  sha256          String?\n  cifrado         Boolean   @default(false)\n  incluyeAdjuntos Boolean   @default(false)\n  /// [{ destinoId, nombre, tipo, ok, error?, ubicacion?, podados? }]\n  destinos        Json?\n  error           String?   @db.Text\n  duracionMs      Int?\n  usuarioId       String?\n  createdAt       DateTime  @default(now())\n  terminadoAt     DateTime?\n\n  @@index([createdAt])\n  @@index([tipo, estado])\n}\n\nmodel TablasISR {\n  id             String   @id @default(cuid())\n  anio           Int\n  rangoDesde     Decimal  @db.Decimal(14, 2)\n  rangoHasta     Decimal? @db.Decimal(14, 2)\n  cuotaFija      Decimal  @db.Decimal(12, 2)\n  porcentaje     Decimal  @db.Decimal(5, 4)\n  excedenteDesde Decimal  @db.Decimal(14, 2)\n  activa         Boolean  @default(true)\n  createdAt      DateTime @default(now())\n}\n\n/// Impuesto personal o vecinal — tabla progresiva por municipio.\n///\n/// Art. 77 de la Ley de Municipalidades: cada municipalidad aprueba su Plan de\n/// Arbitrios cada año, con su propio Anexo de tarifas. Por eso la tabla vive en\n/// base de datos y no en el código: un Plan nuevo se carga sin desplegar.\n///\n/// `porMillar` son lempiras por cada mil de la PORCIÓN del ingreso anual que\n/// cae en este tramo. El impuesto total es la SUMA de todos los tramos que el\n/// ingreso atraviesa, no una tarifa única aplicada al total.\nmodel TablaImpuestoVecinal {\n  id         String   @id @default(cuid())\n  /// Municipio al que corresponde la tabla (p. ej. \"SAN_PEDRO_SULA\").\n  municipio  String\n  anio       Int\n  rangoDesde Decimal  @db.Decimal(14, 2)\n  /// `null` = último tramo, sin techo.\n  rangoHasta Decimal? @db.Decimal(14, 2)\n  porMillar  Decimal  @db.Decimal(8, 4)\n  activa     Boolean  @default(true)\n  createdAt  DateTime @default(now())\n\n  @@unique([municipio, anio, rangoDesde])\n  @@index([municipio, anio, activa])\n}\n\nmodel SalarioMinimo {\n  id            String   @id @default(cuid())\n  anio          Int\n  sector        String   @default(\"GENERAL\")\n  monto         Decimal  @db.Decimal(12, 2)\n  fechaVigencia DateTime @db.Date\n  activo        Boolean  @default(true)\n  createdAt     DateTime @default(now())\n}\n\n// ─── AUDIT TRAIL ─────────────────────────────────────────────────────────────\n\nmodel AuditLog {\n  id            String      @id @default(cuid())\n  accion        AccionAudit\n  tabla         String // nombre de la tabla afectada\n  registroId    String // ID del registro afectado\n  usuarioId     String? // quién lo hizo\n  usuarioEmail  String?\n  valorAnterior Json? // snapshot antes del cambio\n  valorNuevo    Json? // snapshot después del cambio\n  ip            String?\n  userAgent     String?\n  createdAt     DateTime    @default(now())\n\n  @@index([tabla, registroId])\n  @@index([usuarioId])\n  @@index([createdAt])\n}\n\n// ─── NOTIFICACIONES INTERNAS ──────────────────────────────────────────────────\n\nmodel Notificacion {\n  id         String   @id @default(cuid())\n  empleadoId String\n  titulo     String\n  mensaje    String   @db.Text\n  tipo       String   @default(\"INFO\") // INFO | ALERTA | EVALUACION | PLANILLA\n  leida      Boolean  @default(false)\n  accionUrl  String?\n  createdAt  DateTime @default(now())\n\n  @@index([empleadoId, leida])\n}\n\n// ─── DOTACIONES (uniformes, EPP, equipo asignado) ─────────────────────────────\n\nenum CategoriaDotacion {\n  UNIFORME\n  EPP // Equipo de protección personal\n  EQUIPO\n  HERRAMIENTA\n  OTRO\n}\n\nenum EstadoDotacion {\n  ASIGNADO\n  DEVUELTO\n  REPOSICION\n  BAJA\n}\n\nmodel ArticuloDotacion {\n  id            String            @id @default(cuid())\n  nombre        String\n  categoria     CategoriaDotacion @default(OTRO)\n  descripcion   String?\n  requiereTalla Boolean           @default(false)\n  vidaUtilMeses Int? // meses hasta reposición (para programar recambio)\n  activo        Boolean           @default(true)\n  createdAt     DateTime          @default(now())\n  updatedAt     DateTime          @updatedAt\n\n  asignaciones AsignacionDotacion[]\n}\n\nmodel AsignacionDotacion {\n  id               String           @id @default(cuid())\n  empleadoId       String\n  empleado         Empleado         @relation(fields: [empleadoId], references: [id])\n  articuloId       String\n  articulo         ArticuloDotacion @relation(fields: [articuloId], references: [id])\n  cantidad         Int              @default(1)\n  talla            String?\n  fechaEntrega     DateTime         @db.Date\n  fechaVencimiento DateTime?        @db.Date\n  estado           EstadoDotacion   @default(ASIGNADO)\n  observacion      String?\n  entregadoPor     String?\n  createdAt        DateTime         @default(now())\n  updatedAt        DateTime         @updatedAt\n\n  @@index([empleadoId])\n  @@index([estado])\n  @@index([fechaVencimiento])\n}\n\n// ─── RECLUTAMIENTO Y SELECCIÓN ────────────────────────────────────────────────\n\nenum EstadoVacante {\n  ABIERTA\n  PAUSADA\n  CERRADA\n}\n\nenum EtapaCandidato {\n  RECIBIDO\n  PRESELECCION\n  ENTREVISTA\n  OFERTA\n  CONTRATADO\n  RECHAZADO\n}\n\nmodel Vacante {\n  id             String        @id @default(cuid())\n  titulo         String\n  descripcion    String?       @db.Text\n  requisitos     String?       @db.Text\n  departamentoId String?\n  departamento   Departamento? @relation(fields: [departamentoId], references: [id])\n  tipoContrato   TipoContrato  @default(INDEFINIDO)\n  salarioMin     Decimal?      @db.Decimal(12, 2)\n  salarioMax     Decimal?      @db.Decimal(12, 2)\n  plazas         Int           @default(1)\n  esInterna      Boolean       @default(false)\n  estado         EstadoVacante @default(ABIERTA)\n  fechaApertura  DateTime      @default(now())\n  fechaCierre    DateTime?     @db.Date\n  creadoPor      String?\n  /// Visible en el portal público /empleos. Hay que publicarla a propósito.\n  publicada      Boolean       @default(false)\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @updatedAt\n\n  candidatos Candidato[]\n}\n\nmodel Candidato {\n  id               String         @id @default(cuid())\n  vacanteId        String\n  vacante          Vacante        @relation(fields: [vacanteId], references: [id])\n  nombre           String\n  email            String?\n  telefono         String?\n  cvUrl            String?\n  fuente           String?\n  etapa            EtapaCandidato @default(RECIBIDO)\n  notas            String?        @db.Text\n  /// Momento en que aceptó el tratamiento de sus datos al postularse en /empleos.\n  consentimientoAt DateTime?\n  createdAt        DateTime       @default(now())\n  updatedAt        DateTime       @updatedAt\n\n  @@index([vacanteId, etapa])\n}\n\n// ─── CAPACITACIÓN ─────────────────────────────────────────────────────────────\n\nenum TipoCapacitacion {\n  INTERNA\n  EXTERNA\n}\n\nenum EstadoCapacitacion {\n  PLANIFICADA\n  EN_CURSO\n  FINALIZADA\n  CANCELADA\n}\n\nmodel Capacitacion {\n  id                 String             @id @default(cuid())\n  nombre             String\n  descripcion        String?            @db.Text\n  tipo               TipoCapacitacion   @default(INTERNA)\n  proveedor          String?\n  fechaInicio        DateTime           @db.Date\n  fechaFin           DateTime?          @db.Date\n  costoPresupuestado Decimal            @default(0) @db.Decimal(12, 2)\n  costoReal          Decimal?           @db.Decimal(12, 2)\n  estado             EstadoCapacitacion @default(PLANIFICADA)\n  creadoPor          String?\n  createdAt          DateTime           @default(now())\n  updatedAt          DateTime           @updatedAt\n\n  participantes ParticipanteCapacitacion[]\n  materiales    MaterialCapacitacion[]\n}\n\nenum TipoMaterial {\n  MANUAL\n  VIDEO\n  DOCUMENTO\n}\n\n/// Material de una capacitación (manuales y documentos en PDF, videos MP4/WebM, imágenes).\n///\n/// Se guarda en el disco del servidor, fuera de `public/` (UPLOAD_DIR/capacitaciones), y\n/// sólo se entrega en el visor: por partes (Range), con un enlace firmado de vida corta\n/// atado a quien lo pidió y siempre `inline`. Decisión de Edbin, 2026-11-14.\nmodel MaterialCapacitacion {\n  id             String       @id @default(cuid())\n  capacitacionId String\n  capacitacion   Capacitacion @relation(fields: [capacitacionId], references: [id], onDelete: Cascade)\n  titulo         String\n  descripcion    String?\n  tipo           TipoMaterial\n  /// Nombre interno en disco: UUID + extensión. Nunca el que traía el archivo.\n  archivo        String       @unique\n  mime           String\n  tamano         Int\n  orden          Int          @default(0)\n  subidoPor      String?\n  createdAt      DateTime     @default(now())\n\n  vistas VistaMaterial[]\n\n  @@index([capacitacionId, orden])\n}\n\n/// Quién abrió cada material, para el avance de la capacitación.\nmodel VistaMaterial {\n  id         String               @id @default(cuid())\n  materialId String\n  material   MaterialCapacitacion @relation(fields: [materialId], references: [id], onDelete: Cascade)\n  empleadoId String\n  empleado   Empleado             @relation(fields: [empleadoId], references: [id], onDelete: Cascade)\n  primeraVez DateTime             @default(now())\n  ultimaVez  DateTime             @default(now())\n  veces      Int                  @default(1)\n\n  @@unique([materialId, empleadoId])\n}\n\nmodel ParticipanteCapacitacion {\n  id             String       @id @default(cuid())\n  capacitacionId String\n  capacitacion   Capacitacion @relation(fields: [capacitacionId], references: [id])\n  empleadoId     String\n  empleado       Empleado     @relation(fields: [empleadoId], references: [id])\n  asistio        Boolean      @default(false)\n  aprobado       Boolean?\n  calificacion   Decimal?     @db.Decimal(5, 2)\n  observacion    String?\n  createdAt      DateTime     @default(now())\n\n  @@unique([capacitacionId, empleadoId])\n}\n\n// ─── REPOSITORIO DE POLÍTICAS Y PROCEDIMIENTOS ────────────────────────────────\n\nmodel Politica {\n  id          String   @id @default(cuid())\n  titulo      String\n  categoria   String   @default(\"General\")\n  descripcion String?\n  activa      Boolean  @default(true)\n  creadoPor   String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  versiones VersionPolitica[]\n}\n\nmodel VersionPolitica {\n  id           String   @id @default(cuid())\n  politicaId   String\n  politica     Politica @relation(fields: [politicaId], references: [id])\n  numero       Int\n  contenido    String   @db.Text\n  notasCambio  String?\n  vigente      Boolean  @default(true)\n  publicadaPor String?\n  createdAt    DateTime @default(now())\n\n  @@unique([politicaId, numero])\n  @@index([politicaId, vigente])\n}\n\n// ─── CORREO SALIENTE ─────────────────────────────────────────────────────────\n\n/// Servidor SMTP con el que se envían los comprobantes de pago.\n///\n/// Una sola fila (id = \"default\"). Antes el servidor sólo podía fijarse con\n/// variables de entorno, lo que exigía acceso al servidor para cambiar de\n/// proveedor de correo. Si esta fila no existe o está inactiva, el envío cae a\n/// las variables SMTP_* para no romper las instalaciones que ya las usan.\nmodel ConfiguracionCorreo {\n  id              String   @id @default(\"default\")\n  host            String\n  puerto          Int      @default(587)\n  /// SSL/TLS directo (típico puerto 465). Con `false` se negocia STARTTLS (587).\n  seguro          Boolean  @default(false)\n  usuario         String?\n  /// Cifrada con AES-256-GCM. Ver lib/seguridad/cifrado.ts. Nunca sale de la API.\n  passwordCifrado String?\n  remitenteNombre String   @default(\"Recursos Humanos\")\n  remitenteCorreo String\n  activo          Boolean  @default(true)\n  actualizadoPor  String?\n  updatedAt       DateTime @updatedAt\n  createdAt       DateTime @default(now())\n}\n\n// ─── INTEGRACIÓN SAP BUSINESS ONE ─────────────────────────────────────────────\n\n/// Cuándo se manda a SAP el asiento de una planilla.\nenum ModoEnvioSap {\n  /// Sólo con el botón «Enviar a SAP» de la planilla.\n  MANUAL\n  /// Al pasar a APROBADA (la planilla ya está sellada con su huella).\n  AL_APROBAR\n  /// Al pasar a PAGADA (fecha contable = fecha real de pago).\n  AL_PAGAR\n}\n\nenum EstadoEnvioSap {\n  /// En cola; `proximoIntentoAt` dice cuándo le toca.\n  PENDIENTE\n  /// Un proceso lo tiene tomado (`bloqueadoHasta`).\n  ENVIANDO\n  /// SAP devolvió el número de asiento.\n  ENVIADO\n  /// Error de negocio o reintentos agotados: hace falta una persona.\n  ERROR\n  /// La planilla cambió después de encolar: el payload ya no vale.\n  CANCELADO\n}\n\nenum TipoEnvioSap {\n  ASIENTO\n  /// Asiento inverso, al anular una planilla que ya estaba en SAP.\n  REVERSO\n}\n\n/// Conexión con el Service Layer de SAP B1 y comportamiento del envío.\n/// Una sola fila (id = \"default\"). La contraseña va cifrada (lib/seguridad/cifrado.ts).\nmodel IntegracionSap {\n  id                    String       @id @default(\"default\")\n  activo                Boolean      @default(false)\n  /// https://servidor:50000/b1s/v1/\n  urlBase               String\n  companyDb             String\n  usuario               String\n  passwordCifrado       String?\n  modoEnvio             ModoEnvioSap @default(MANUAL)\n  incluirProvisiones    Boolean      @default(true)\n  porCentroCosto        Boolean      @default(false)\n  /// Dimensión de B1 (1 a 5) en la que viven los centros de costo.\n  dimensionCentro       Int          @default(1)\n  /// \"PAGO\" = fecha de pago de la planilla; \"FIN_PERIODO\" = último día del período.\n  fechaContable         String       @default(\"PAGO\")\n  /// TransactionCode de B1 (4 caracteres), opcional.\n  codigoTransaccion     String?\n  /// Serie de numeración de asientos en B1, opcional.\n  serie                 Int?\n  /// Variables: {tipo} {desde} {hasta} {empresa}.\n  memoPlantilla         String       @default(\"Planilla {tipo} {desde} al {hasta}\")\n  /// Longitudes leídas del $metadata del servidor en la última prueba.\n  longitudMemo          Int          @default(50)\n  longitudLineMemo      Int          @default(50)\n  longitudReferencia    Int          @default(100)\n  // ─── Base de datos de SAP (SQL Server), SÓLO LECTURA ─────────────────────\n  // Valida la base de la empresa y lista las empresas del servidor. La\n  // aplicación nunca escribe ahí: los asientos van por el Service Layer.\n  /// Servidor o IP del SQL Server de SAP. Vacío = sin conexión a la base.\n  dbServidor            String?\n  dbPuerto              Int          @default(1433)\n  /// Instancia nombrada (SERVIDOR\\INSTANCIA); con ella el puerto lo resuelve SQL Browser.\n  dbInstancia           String?\n  dbUsuario             String?\n  /// Cifrada con AES-256-GCM, como la del Service Layer. Nunca sale de la API.\n  dbPasswordCifrado     String?\n  dbCifrar              Boolean      @default(false)\n  dbConfiarCertificado  Boolean      @default(true)\n  dbUltimaPruebaAt      DateTime?\n  dbUltimaPruebaOk      Boolean?\n  dbUltimaPruebaDetalle String?      @db.Text\n  /// SAP tiene varias sucursales: cada línea del asiento lleva BPLID.\n  usaSucursales         Boolean      @default(false)\n  /// Sucursal de SAP para las planillas de toda la empresa (sin sucursal local).\n  sapBplIdPorDefecto    Int?\n  /// \"LOCAL\" = catálogo propio; \"SAP\" = espejo del plan de cuentas de SAP (sólo lectura aquí).\n  catalogoOrigen        String       @default(\"LOCAL\")\n  catalogoImportadoAt   DateTime?\n  catalogoCuentas       Int?\n  ultimaPruebaAt        DateTime?\n  ultimaPruebaOk        Boolean?\n  ultimaPruebaDetalle   String?      @db.Text\n  versionSap            String?\n  actualizadoPor        String?\n  createdAt             DateTime     @default(now())\n  updatedAt             DateTime     @updatedAt\n}\n\n/// Cola de salida: un asiento (o su reverso) por planilla.\n///\n/// `hashCalculo` es la huella de cierre con la que se construyó `payload`:\n/// si la planilla se reabre y recalcula, el envío se cancela en vez de mandar\n/// cifras viejas. `payload` se guarda tal cual se envía, para la auditoría.\nmodel SapEnvioAsiento {\n  id               String         @id @default(cuid())\n  planillaId       String\n  planilla         Planilla       @relation(fields: [planillaId], references: [id])\n  tipo             TipoEnvioSap   @default(ASIENTO)\n  estado           EstadoEnvioSap @default(PENDIENTE)\n  hashCalculo      String\n  payload          Json\n  respuesta        Json?\n  /// JdtNum (TransId) del asiento en SAP.\n  sapTransId       Int?\n  /// Número visible del asiento en SAP.\n  sapNumero        Int?\n  intentos         Int            @default(0)\n  proximoIntentoAt DateTime?\n  bloqueadoHasta   DateTime?\n  errorCodigo      String?\n  errorMensaje     String?        @db.Text\n  errorTraducido   String?        @db.Text\n  esTransitorio    Boolean?\n  reversoDeId      String?\n  creadoPor        String?\n  enviadoAt        DateTime?\n  createdAt        DateTime       @default(now())\n  updatedAt        DateTime       @updatedAt\n\n  bitacora SapBitacora[]\n\n  @@unique([planillaId, tipo])\n  @@index([estado, proximoIntentoAt])\n}\n\n/// Un renglón por intento de envío, con lo que respondió SAP.\nmodel SapBitacora {\n  id          String          @id @default(cuid())\n  envioId     String\n  envio       SapEnvioAsiento @relation(fields: [envioId], references: [id], onDelete: Cascade)\n  intento     Int\n  httpStatus  Int?\n  duracionMs  Int\n  /// OK | RECONCILIADO | ERROR | CANCELADO\n  resultado   String\n  errorCodigo String?\n  mensaje     String?         @db.Text\n  createdAt   DateTime        @default(now())\n\n  @@index([envioId, createdAt])\n}\n\n// ─── DOCUMENTOS DESDE PLANTILLA ───────────────────────────────────────────────\n\nenum TipoPlantillaDocumento {\n  CONSTANCIA_TRABAJO\n  CONSTANCIA_SALARIO\n  CONTRATO\n  CARTA\n  OTRO\n}\n\n/// Constancias, contratos y cartas con variables del expediente ({{empleado.nombreCompleto}}).\nmodel PlantillaDocumento {\n  id             String                 @id @default(cuid())\n  codigo         String                 @unique\n  nombre         String\n  tipo           TipoPlantillaDocumento\n  /// Título impreso en el documento.\n  titulo         String\n  /// Texto con variables; los párrafos se separan con una línea en blanco.\n  contenido      String                 @db.Text\n  /// El empleado puede emitirla para sí mismo desde Mi espacio.\n  autoservicio   Boolean                @default(false)\n  /// Sembradas por la aplicación: se editan, no se borran.\n  esSistema      Boolean                @default(false)\n  activo         Boolean                @default(true)\n  actualizadoPor String?\n  createdAt      DateTime               @default(now())\n  updatedAt      DateTime               @updatedAt\n\n  emitidos DocumentoEmitido[]\n}\n\n/// Cada documento emitido, con el texto ya resuelto: el PDF se regenera idéntico.\nmodel DocumentoEmitido {\n  id              String             @id @default(cuid())\n  /// Correlativo por año, p. ej. 2026-000123.\n  folio           String             @unique\n  plantillaId     String\n  plantilla       PlantillaDocumento @relation(fields: [plantillaId], references: [id])\n  empleadoId      String\n  empleado        Empleado           @relation(fields: [empleadoId], references: [id])\n  destinatario    String?\n  titulo          String\n  contenido       String             @db.Text\n  firmanteNombre  String?\n  firmanteCargo   String?\n  emitidoPor      String?\n  porAutoservicio Boolean            @default(false)\n  anulado         Boolean            @default(false)\n  createdAt       DateTime           @default(now())\n\n  @@index([empleadoId, createdAt])\n}\n\n// ─── SOLICITUDES DE PRÉSTAMO Y ANTICIPO ───────────────────────────────────────\n\nenum TipoSolicitudPrestamo {\n  PRESTAMO\n  ADELANTO\n}\n\nenum EstadoSolicitudPrestamo {\n  PENDIENTE\n  APROBADA\n  RECHAZADA\n  CANCELADA\n}\n\n/// El empleado la pide en Mi espacio; al aprobarla se crea la deducción a plazo.\nmodel SolicitudPrestamo {\n  id                 String                  @id @default(cuid())\n  empleadoId         String\n  empleado           Empleado                @relation(fields: [empleadoId], references: [id])\n  tipo               TipoSolicitudPrestamo\n  monto              Decimal                 @db.Decimal(12, 2)\n  cuotas             Int\n  /// Cuota por período de pago de la planilla del empleado.\n  cuotaPeriodo       Decimal                 @db.Decimal(12, 2)\n  motivo             String?                 @db.Text\n  estado             EstadoSolicitudPrestamo @default(PENDIENTE)\n  /// Límite de descuento estimado al solicitar (Arts. 371 y 372 C.T.).\n  limiteCuotaPeriodo Decimal?                @db.Decimal(12, 2)\n  excedeLimite       Boolean                 @default(false)\n  resueltoPor        String?\n  resueltoAt         DateTime?\n  observacion        String?                 @db.Text\n  deduccionId        String?                 @unique\n  deduccion          DeduccionEmpleado?      @relation(fields: [deduccionId], references: [id])\n  createdAt          DateTime                @default(now())\n  updatedAt          DateTime                @updatedAt\n\n  @@index([estado, createdAt])\n  @@index([empleadoId])\n}\n\n// ─── INCAPACIDADES DEL IHSS ───────────────────────────────────────────────────\n\nenum TipoIncapacidad {\n  ENFERMEDAD_COMUN\n  ACCIDENTE_COMUN\n  RIESGO_PROFESIONAL\n  MATERNIDAD\n}\n\nenum EmisorIncapacidad {\n  IHSS\n  MEDICO_PRIVADO\n  SISTEMA_MEDICO_EMPRESA\n}\n\n/// Certificado de incapacidad temporal. Las reglas con que se registró quedan\n/// congeladas: la planilla de un período cerrado se puede reproducir aunque\n/// después cambien los parámetros.\nmodel Incapacidad {\n  id                    String            @id @default(cuid())\n  empleadoId            String\n  empleado              Empleado          @relation(fields: [empleadoId], references: [id])\n  tipo                  TipoIncapacidad\n  emisor                EmisorIncapacidad @default(IHSS)\n  fechaInicio           DateTime          @db.Date\n  fechaFin              DateTime          @db.Date\n  dias                  Int\n  numeroCertificado     String?\n  /// Prórroga de otra incapacidad: no reinicia los días a cargo del patrono.\n  prorrogaDeId          String?\n  prorrogaDe            Incapacidad?      @relation(\"ProrrogaIncapacidad\", fields: [prorrogaDeId], references: [id])\n  prorrogas             Incapacidad[]     @relation(\"ProrrogaIncapacidad\")\n  /// Días iniciales que paga el patrono al 100 % (Art. 71 Reglamento IHSS 2020).\n  diasPatrono           Int\n  /// Porcentaje del salario que paga el IHSS como subsidio desde el día siguiente.\n  porcentajeSubsidio    Decimal           @db.Decimal(5, 2)\n  /// Porcentaje del salario que el patrono sigue pagando en los días del IHSS.\n  porcentajeComplemento Decimal           @db.Decimal(5, 2)\n  archivoUrl            String?\n  observacion           String?           @db.Text\n  anulada               Boolean           @default(false)\n  registradoPor         String?\n  createdAt             DateTime          @default(now())\n  updatedAt             DateTime          @updatedAt\n\n  @@index([empleadoId, fechaInicio])\n  @@index([fechaInicio, fechaFin])\n}\n\n// ─── HORARIOS Y TURNOS ────────────────────────────────────────────────────────\n\n/// Arts. 321 y 322 C.T.: diurna 8 h, mixta 7 h, nocturna 6 h diarias como máximo.\nenum TipoJornada {\n  DIURNA\n  MIXTA\n  NOCTURNA\n}\n\nmodel Turno {\n  id                 String      @id @default(cuid())\n  codigo             String      @unique\n  nombre             String\n  tipoJornada        TipoJornada @default(DIURNA)\n  /// \"HH:MM\". Una salida anterior a la entrada significa que cruza la medianoche.\n  horaEntrada        String\n  horaSalida         String\n  /// Horas ordinarias; por encima empieza la extra.\n  jornadaHoras       Decimal     @db.Decimal(4, 2)\n  almuerzoMinutos    Int         @default(60)\n  almuerzoDesdeHoras Decimal     @default(6) @db.Decimal(4, 2)\n  /// Minutos de gracia antes de contar una llegada tarde.\n  toleranciaMinutos  Int         @default(5)\n  /// Días laborales ISO (1 = lunes … 7 = domingo), separados por coma.\n  diasLaborales      String      @default(\"1,2,3,4,5\")\n  /// Turno de quien no tiene asignación. Sólo uno.\n  esPorDefecto       Boolean     @default(false)\n  activo             Boolean     @default(true)\n  createdAt          DateTime    @default(now())\n  updatedAt          DateTime    @updatedAt\n\n  asignaciones AsignacionTurno[]\n  horarioDias  HorarioDia[]\n}\n\n/// Qué turno tiene un empleado desde una fecha. La vigente es la de `desde` más reciente.\nmodel AsignacionTurno {\n  id         String    @id @default(cuid())\n  empleadoId String\n  empleado   Empleado  @relation(fields: [empleadoId], references: [id], onDelete: Cascade)\n  turnoId    String\n  turno      Turno     @relation(fields: [turnoId], references: [id])\n  desde      DateTime  @db.Date\n  hasta      DateTime? @db.Date\n  creadoPor  String?\n  createdAt  DateTime  @default(now())\n\n  @@index([empleadoId, desde])\n}\n\n// ─── FORMATOS DE ARCHIVO PARA EL BANCO ────────────────────────────────────────\n\n/// Disposición del archivo de pago que exige cada banco. Se configura, no se programa.\nmodel FormatoBanco {\n  id             String   @id @default(cuid())\n  nombre         String\n  /// Sólo empleados cuyo banco contenga este texto, sin distinguir mayúsculas. Vacío = todos.\n  filtroBanco    String?\n  /// DELIMITADO | ANCHO_FIJO\n  tipo           String   @default(\"DELIMITADO\")\n  delimitador    String   @default(\",\")\n  encabezado     Boolean  @default(true)\n  /// [{ campo, titulo, ancho?, alinear?, relleno?, valor?, formato? }]\n  columnas       Json\n  extension      String   @default(\"csv\")\n  /// utf8 | latin1\n  codificacion   String   @default(\"utf8\")\n  /// CRLF | LF\n  finLinea       String   @default(\"CRLF\")\n  /// Línea final con número de registros y total.\n  lineaTotal     Boolean  @default(false)\n  esSistema      Boolean  @default(false)\n  activo         Boolean  @default(true)\n  actualizadoPor String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n}\n\n// ─── SALUD Y FAMILIA ──────────────────────────────────────────────────────────\n\n/// Datos de salud: sólo con `empleados.salud` o el propio empleado.\nmodel FichaMedica {\n  id                   String   @id @default(cuid())\n  empleadoId           String   @unique\n  empleado             Empleado @relation(fields: [empleadoId], references: [id], onDelete: Cascade)\n  tipoSangre           String?\n  alergias             String?  @db.Text\n  enfermedadesCronicas String?  @db.Text\n  medicamentos         String?  @db.Text\n  discapacidad         String?\n  medicoNombre         String?\n  medicoTelefono       String?\n  observaciones        String?  @db.Text\n  actualizadoPor       String?\n  createdAt            DateTime @default(now())\n  updatedAt            DateTime @updatedAt\n}\n\nenum Parentesco {\n  CONYUGE\n  COMPANERO_HOGAR\n  HIJO\n  PADRE\n  MADRE\n  HERMANO\n  OTRO\n}\n\nmodel FamiliarEmpleado {\n  id                   String     @id @default(cuid())\n  empleadoId           String\n  empleado             Empleado   @relation(fields: [empleadoId], references: [id], onDelete: Cascade)\n  nombre               String\n  parentesco           Parentesco\n  fechaNacimiento      DateTime?  @db.Date\n  identidad            String?\n  telefono             String?\n  esDependiente        Boolean    @default(false)\n  esContactoEmergencia Boolean    @default(false)\n  createdAt            DateTime   @default(now())\n  updatedAt            DateTime   @updatedAt\n\n  @@index([empleadoId])\n}\n\n/// A quién se pagan las prestaciones en caso de muerte del trabajador.\nmodel BeneficiarioEmpleado {\n  id         String     @id @default(cuid())\n  empleadoId String\n  empleado   Empleado   @relation(fields: [empleadoId], references: [id], onDelete: Cascade)\n  nombre     String\n  parentesco Parentesco\n  identidad  String?\n  telefono   String?\n  porcentaje Decimal    @db.Decimal(5, 2)\n  createdAt  DateTime   @default(now())\n  updatedAt  DateTime   @updatedAt\n\n  @@index([empleadoId])\n}\n\n// ─── HORARIOS ROTATIVOS ───────────────────────────────────────────────────────\n// Planificación por día de varias sucursales: cobertura mínima por puesto y\n// franja, preferencias del personal y planes generados (src/lib/horarios). Un\n// plan PUBLICADO es la fuente más específica del turno de cada día (turnoDe).\n\n/// Personal mínimo de un puesto en una franja horaria de una sucursal.\nmodel CoberturaSucursal {\n  id         String   @id @default(cuid())\n  sucursalId String\n  sucursal   Sucursal @relation(fields: [sucursalId], references: [id], onDelete: Cascade)\n  puestoId   String\n  puesto     Puesto   @relation(fields: [puestoId], references: [id], onDelete: Cascade)\n  /// Días ISO separados por coma (1 = lunes … 7 = domingo).\n  dias       String   @default(\"1,2,3,4,5,6,7\")\n  /// \"HH:MM\". Una hora final igual o anterior a la inicial cruza la medianoche.\n  desde      String\n  hasta      String\n  minimo     Int\n  /// «Pico almuerzo», «Valle»…\n  etiqueta   String?\n  activo     Boolean  @default(true)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@index([sucursalId])\n}\n\n/// Horario de atención al público de una sucursal, por día de la semana.\nmodel HorarioAtencion {\n  id         String   @id @default(cuid())\n  sucursalId String\n  sucursal   Sucursal @relation(fields: [sucursalId], references: [id], onDelete: Cascade)\n  /// Día ISO (1 = lunes … 7 = domingo).\n  dia        Int\n  apertura   String?\n  cierre     String?\n  cerrado    Boolean  @default(false)\n  updatedAt  DateTime @updatedAt\n\n  @@unique([sucursalId, dia])\n}\n\n/// Disponibilidad y restricciones de horario de una persona (estudios, salud, traslados).\nmodel PreferenciaHorario {\n  id                   String   @id @default(cuid())\n  empleadoId           String   @unique\n  empleado             Empleado @relation(fields: [empleadoId], references: [id], onDelete: Cascade)\n  permiteTraslado      Boolean  @default(false)\n  /// Sucursales aceptadas para traslado; vacío = cualquiera.\n  sucursalesTraslado   String[] @default([])\n  /// \"HH:MM\"; vacío = sin restricción.\n  noAntesDe            String?\n  noDespuesDe          String?\n  /// Días ISO en que rige la restricción de horas; vacío = todos.\n  diasRestriccion      String   @default(\"\")\n  /// Nada nocturno ni mixto.\n  soloDiurna           Boolean  @default(false)\n  diasNoDisponible     String   @default(\"\")\n  diaDescansoPreferido Int?\n  motivo               String?\n  updatedAt            DateTime @updatedAt\n}\n\nenum EstadoPlanHorario {\n  BORRADOR\n  PUBLICADO\n  ARCHIVADO\n}\n\nenum EstadoDiaHorario {\n  TURNO\n  DESCANSO\n  AUSENCIA\n}\n\n/// Plan de horarios rotativos de un período (semana, quincena o mes).\nmodel PlanHorario {\n  id            String            @id @default(cuid())\n  nombre        String\n  desde         DateTime          @db.Date\n  hasta         DateTime          @db.Date\n  sucursalesIds String[]\n  estado        EstadoPlanHorario @default(BORRADOR)\n  /// Reglas con que se generó (descanso entre jornadas, víspera, rotación…).\n  reglas        Json\n  /// Conteo de alertas al último guardado: { errores, avisos, faltantes }.\n  resumen       Json?\n  creadoPor     String?\n  publicadoPor  String?\n  publicadoAt   DateTime?\n  createdAt     DateTime          @default(now())\n  updatedAt     DateTime          @updatedAt\n  dias          HorarioDia[]\n\n  @@index([estado, desde])\n}\n\n/// Préstamo TEMPORAL de un empleado a otra sucursal para los horarios rotativos.\n///\n/// No cambia su sucursal, su planilla ni dónde se le paga: sólo dónde trabaja esos días.\n/// Mientras dura, los planes de la sucursal de destino lo incluyen como personal de ella\n/// (ausente fuera de estas fechas) y los de su sucursal lo dan por ausente («Trasladado a…»).\n/// Decisión de Edbin, 2026-11-14.\nmodel TrasladoTemporal {\n  id                String   @id @default(cuid())\n  empleadoId        String\n  empleado          Empleado @relation(fields: [empleadoId], references: [id], onDelete: Cascade)\n  /// Su sucursal cuando se registró (informativo: la de verdad sigue en Empleado).\n  sucursalOrigenId  String\n  sucursalDestinoId String\n  sucursalDestino   Sucursal @relation(fields: [sucursalDestinoId], references: [id])\n  desde             DateTime @db.Date\n  hasta             DateTime @db.Date\n  motivo            String?\n  anulado           Boolean  @default(false)\n  creadoPor         String?\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  @@index([sucursalDestinoId, desde, hasta])\n  @@index([empleadoId, desde])\n}\n\n/// Un día de una persona en un plan.\nmodel HorarioDia {\n  id         String           @id @default(cuid())\n  planId     String\n  plan       PlanHorario      @relation(fields: [planId], references: [id], onDelete: Cascade)\n  empleadoId String\n  empleado   Empleado         @relation(fields: [empleadoId], references: [id], onDelete: Cascade)\n  fecha      DateTime         @db.Date\n  estado     EstadoDiaHorario\n  /// Sucursal donde trabaja ese día (otra que la suya = traslado).\n  sucursalId String?\n  turnoId    String?\n  turno      Turno?           @relation(fields: [turnoId], references: [id])\n  /// Minutos desde la medianoche del día; la salida puede pasar de 1440.\n  entrada    Int?\n  salida     Int?\n  pausa      Int              @default(0)\n  esTraslado Boolean          @default(false)\n  /// Editado a mano después de generarse.\n  manual     Boolean          @default(false)\n  /// Ausencia (vacaciones, incapacidad) o razón de un descanso adicional.\n  motivo     String?\n\n  @@unique([planId, empleadoId, fecha])\n  @@index([empleadoId, fecha])\n}\n"
}

